-- 007_seed_fra_aml_cft_decisions.sql
-- الدفعة الأولى من تشريعات/قرارات مكافحة غسل الأموال وتمويل الإرهاب (FRA)
-- المصدر: fra.gov.eg -> بوابة تشريعات الهيئة -> تشريعات مكافحة غسل الأموال وتمويل الإرهاب
-- يضيف تصنيفاً جديداً 'aml_cft' (نفس نمط إضافة 'insurance' فى 003) لأن غسل
-- الأموال مجال قانونى منفصل جوهرياً عن التأمين.
-- قابل لإعادة التشغيل بأمان (idempotent) — نفس نمط بقية migrations/.

BEGIN;

ALTER TABLE laws DROP CONSTRAINT IF EXISTS laws_category_check;
ALTER TABLE laws ADD CONSTRAINT laws_category_check
  CHECK (category IN ('labor','rent','personal_status','traffic','consumer_protection','insurance','aml_cft','legal_profession','other'));

-- ===== alamiria_2024_161 : قرار 161/2024 (مُهيكَل، 20 مادة) =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (161, 2024, $t1$قرار مجلس إدارة الهيئة رقم (161) لسنة 2024 بشأن الضوابط الرقابية فى مجال مكافحة غسل الأموال وتمويل الإرهاب للجهات العاملة فى مجال الأنشطة المالية غير المصرفية (نسخة محدثة)$t1$, $t1$قرار مجلس إدارة الهيئة رقم (161) لسنة 2024 بشأن الضوابط الرقابية فى مجال مكافحة غسل الأموال وتمويل الإرهاب للجهات العاملة فى مجال الأنشطة المالية غير المصرفية (نسخة محدثة)$t1$, 'aml_cft', 'in_force', $u1$https://fra.gov.eg/wp-content/uploads/2024/10/alamiria_2024_161.pdf$u1$, '2024-10-13')
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art_alamiria_2024_161_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b2$نطاق التطبيق
تسرى ضوابط مكافحة غسل الأموال وتمويل الإرهاب الواردة بهذا القرار علـى
البورصات المصرية والمؤسسات المالية والأشخاص الطبيعيين المرخص لهم بمزاولـة
أى أعمال تتصل بأحد الأنشطة المالية غير المصرفية على النحـو الـوارد بـالقوانين
 المنظمة لها .
كما تسرى أحكام قانون مكافحة غسل الأمـوال ولائحتـه التنفيذيـة والقـرارات
 الصادرة تنفيذ ًا لهما فيما لم يرد بشأنه نص خاص فى هذا القرار .
