٥ الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤$b2$, '2024-10-13', 'active' FROM ins_art_alamiria_2024_161_1;
WITH ins_art_alamiria_2024_161_2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b3$التعريفات
فى تطبيق أحكام هذا القرار يقصد بالكلمات والمصطلحات الآتية المعنـى المبـين
 قرين كل منها :
 الهيئة :الهيئة العامة للرقابة المالية .
الوحدة :وحدة مكافحة غسل الأموال وتمويل الإرهاب المنـشأة بقـرار رئـيس
 الجمهورية رقم ١٦٤لسنة ٢٠٠٢
القانون ولائحته التنفيذية :قانون مكافحة غسل الأموال الصادر بالقـانون رقـم
 ٨٠لسنة ٢٠٠٢ولائحته التنفيذية .
المؤسسات المالية :الأشخاص الاعتبارية المرخص لها مـن الهيئـة بمزاولـة
 الأنشطة المالية غير المصرفية .
غسل الأموال :كل فعل من الأفعال المنصوص عليها فى المادة ) (٢من قـانون
 مكافحة غسل الأموال الصادر بالقانون رقم ٨٠لسنة ٢٠٠٢
تمويل الإرهاب :كل فعل من الأفعال المنصوص عليها فى المادة ) (٣من قـانون
مكافحة الإرهاب الصادر بالقانون رقم ٩٤لسنة ، ٢٠١٥وكـل فعـل مـن الأفعـال
المنصوص عليها فى تعريف تمويل الإرهاب على النحو الـوارد باللائحـة التنفيذيـة
 لقانون مكافحة غسل الأموال .
الكيانات الإرهابية :الجمعيات أو المنظمات أو الجماعات أو العصابات أو الخلايا
أو الشركات أو الاتحادات وما فى حكمها أو غيرها من التجمعات أيا كانـت طبيعتهـا
أو شكلها القانونى أو الواقعى ،متى مارست أيا من الأفعال المنصوص عليها فى المادة
 ) (١من قانون تنظيم قوائم الكيانات الإرهابية والإرهابيين رقم ٨لسنة ٢٠١٥
القوائم السلبية :هى القوائـم الصادرة وفق أحكـام القانون رقم ٨لسنة ٢٠١٥
فى شأن تنظيم قوائم الكيانات الإرهابية والإرهابيين ،والقوائم المدرج بها جميع الأشخاص
 والكيانات الخاضعة لعقوبات مالية محددة وفق ًا لقرارات مجلس الأمن ذات الصلة .
 الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤ ٦
العمليات غير العادية :هى العمليات التى تبدو استثنائية عن نمط العمليات المعتادة
من قبل العملاء ويتم تحديدها من خلال التقارير والأنظمة الداخلية بالمؤسسات المالية .
العمليات المشتبه فيها :هى العمليات التى ينتج عن فحـصها ظهـور أسـباب
موضوعية للاشتباه فى أنها تشكل متحصلات من أية جريمة أو تتضمن غسل أمـوال
 أو تمويل إرهاب .
المتحصلات :الأموال الناتجة أو العائدة بطريق مباشـر أو غيـر مباشـر مـن
 ارتكاب أية جريمة أصلية .
الجريمة الأصلية :كل فعل يشكل جناية أو جنحة بموجب القانون المصرى سواء
 ارتكب داخل البلاد أو خارجها متى كان معاقبا عليه فى كلا البلدين .
العميل :الشخص الطبيعى أو الاعتبـارى أو الترتيـب القـانونى الـذى تفـتح
 المؤسسات المالية حسابا باسمه أو تنفذ عملية لحسابه أو تقدم له خدمة .
المستفيد الحقيقى :الشخص الطبيعى الذى تـؤول لـه فعليـا ملكيـة العميـل
أو السيطرة عليه أو الشخص الطبيعى الذى يتم تنفيذ عملية نيابة عنه بمـا فـى ذلـك
الأشخاص الذين يمارسون بالفعل سيطرة فعالة على العميل سواء كان العميل شخـصا
 اعتباريا أو ترتيبا قانونيا .
الترتيبات القانونية :الصناديـق الاستئمانية ) (Trustsأو أية ترتيبـات قانونيـة
مماثلة ،وتعد الصناديق الاستئمانية علاقة قانونية تنشأ من قبل موص يعهد من خلالها
إلى وصى بإدارة أموال مملوكة للموصى لمصلحة مستفيد أو أكثر ويمكن أن تتـضمن
 هذه العلاقة القانونية تحديد رقيب مستقل على الصندوق وتحديد اختصاصاته .
علاقة العمل :أى علاقة تنشأ بين المؤسسات المالية التى تزاول أى من الأنشطة
المالية غير المصرفية وعملائها وتتصل بالأنشطة أو الخدمات التى تقدمها تلك المؤسسات .
تجميد الأموال :الحظر المؤقت الذى يفرض على نقـل الأمـوال أو الأصـول
 أو تحريكها أو تبديلها أو تحويلها أو التصرف فيها .
٧ الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤
دون تأخير :فورا فى غضون ساعات من صدور القرار بتحديث قوائم مجلـس
الأمن ونشره على الموقع الإلكترونى له ،أو نشر القرار بتحـديث قـائمتى الكيانـات
الإرهابية والإرهابيين المحلية بالجريدة الرسمية ،سواء كان هذا التحـديث بالإضـافة
 أو الحذف أو التعديل .
