 أحكام عامة$b3$, '2024-10-13', 'active' FROM ins_art_alamiria_2024_161_2;
WITH ins_art_alamiria_2024_161_3 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 3, NULL, $b4$المبادئ الأساسية
يتعين على المخاطبين بأحكام هذا القرار مـن الأشـخاص الاعتباريـة الالتـزام
 بالمبادئ الآتية :
 المبدأ الأول :المسئولية :
وضع واعتماد سياسة واضحة فى شأن مكافحة غسل الأموال وتمويل الإرهاب ،
ووضع القواعد والإجراءات والنظم الداخلية التى تساعدها على تحقيق ذلك ،أخذ ًا فـى
الاعتبار طبيعة النشاط الذى تزاوله وحجمه ونوعية العملاء والمنتجـات أو الخـدمات
المقدمة والتأكد بشكل مستمر من الالتزام التـام بالمتطلبـات القانونيـة والإجـراءات
 التنظيمية وفق ًا للقانون ولائحته التنفيذية وهذه الضوابط والقواعد الأخرى ذات الصلة .
 المبدأ الثانى :المنهج القائم على أساس المخاطر :
اعتماد منهج قائم على أساس المخاطر وفق ًا لمتطلبات القانون ولائحتـه التنفيذيـة
والضوابط الواردة بهذا القرار ،يتضمن تحديد وتقييم وفهم مخـاطر غـسل الأمـوال
وتمويل الإرهاب التى يحتمل التعرض لها ،وتوثيق ذلك بشكل مكتوب والكترونـى ،
وتحديث هذا التقييم بشكل دورى وكذا المعلومات المرتبطة به ،على أن يراعـى فـى
ذلك أية مخاطر يتم تحديدها على المستوى المحلى وأى متغيرات قد تغير من درجـات
 مخاطر غسل الأموال وتمويل الإرهاب .
 الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤ ٨
كما يتعين على الأشخاص الاعتبارية المخاطبين بأحكام هذا القرار ،تحديد وتقييم
مخاطر غسل الأموال وتمويل الإرهاب التـى قـد تنـشأ عـن اسـتخدامها للأنظمـة
التكنولوجية الحديثة أثناء تقديم خدماتها ومنتجاتها ،أو تقديم أية خـدمات أو منتجـات
جديدة تعتمد على هذه الأنظمة واتخاذ الإجراءات المناسـبة لإدارة تلـك المخـاطر ،
 على أن يراعى فى ذلك ما يلى :
 أنواع العملاء الحاليين والمرتقبين .
 المنتجات والخدمات التى تقدمها المؤسسة أو تعتزم تقديمها .
 التقنيات التى تستخدمها المؤسسة أو تعتزم استخدامها .
 مخاطر الاعتماد على أطراف خارجية ،ومخاطر المناطق الجغرافية .
نتائج التقييم الوطنى لمخاطر غسل الأموال وتمويل الإرهاب وتحديثاته بالإضافة إلى
 نتائج أى تقييمات أخرى للمخاطر تقوم الهيئة أو الوحدة بموافاة المؤسسة المالية بها .
الأحداث الداخلية التى تشكل تأثيرا على مخاطر غسل الأموال وتمويل الإرهاب ؛
ومنها التغيرات فى الإدارة أو هيكل الملكية للمؤسسة المالية ،والمخـاطر التـشغيلية ،
ومخاطر السمعة ،والمخاطر القانونية ،والتغييرات الرئيسية فـى الأنـشطة الماليـة
 الحالية ونتائج أى عمليات تفتيش داخلى أو خارجى .
الاعتماد على عناصر نوعية وكمية مثل نوع وحجم العمليات المالية التـى يقـوم
 بتنفيذها العميل .
كما يتعين عليهم اتخاذ التدابير والإجراءات اللازمة للتعامل مع المخاطر التى تـم
 التعرف عليها .
 المبدأ الثالث :حسن الاختيار والتدريب المستمر :
إقرار سياسات وإجراءات وافية لاختيار وتعيين الكوادر البـشرية التـى تتمتـع
بالكفاءة والمهارة المهنية والتأكد من نزاهتهم ،وإخـضاع العـاملين لـديهم الحـاليين
والجدد للتدريب المستمر فى مجال مكافحة غسل الأموال وتمويل الإرهاب على النحـو
 الوارد بهذا القرار .$b4$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b4$المبادئ الأساسية
يتعين على المخاطبين بأحكام هذا القرار مـن الأشـخاص الاعتباريـة الالتـزام
 بالمبادئ الآتية :
 المبدأ الأول :المسئولية :
وضع واعتماد سياسة واضحة فى شأن مكافحة غسل الأموال وتمويل الإرهاب ،
ووضع القواعد والإجراءات والنظم الداخلية التى تساعدها على تحقيق ذلك ،أخذ ًا فـى
الاعتبار طبيعة النشاط الذى تزاوله وحجمه ونوعية العملاء والمنتجـات أو الخـدمات
المقدمة والتأكد بشكل مستمر من الالتزام التـام بالمتطلبـات القانونيـة والإجـراءات
 التنظيمية وفق ًا للقانون ولائحته التنفيذية وهذه الضوابط والقواعد الأخرى ذات الصلة .
 المبدأ الثانى :المنهج القائم على أساس المخاطر :
اعتماد منهج قائم على أساس المخاطر وفق ًا لمتطلبات القانون ولائحتـه التنفيذيـة
والضوابط الواردة بهذا القرار ،يتضمن تحديد وتقييم وفهم مخـاطر غـسل الأمـوال
وتمويل الإرهاب التى يحتمل التعرض لها ،وتوثيق ذلك بشكل مكتوب والكترونـى ،
وتحديث هذا التقييم بشكل دورى وكذا المعلومات المرتبطة به ،على أن يراعـى فـى
ذلك أية مخاطر يتم تحديدها على المستوى المحلى وأى متغيرات قد تغير من درجـات
 مخاطر غسل الأموال وتمويل الإرهاب .
