SELECT id, 1, $b5$إجراءات العناية الواجبة بالعملاء
يجب على المخاطبين بأحكام هذا القرار الالتـزام بـإجراءات العنايـة الواجبـة
بالعملاء وغيرها من القواعد والضوابط والإجـراءات ذات الـصلة بمكافحـة غـسل
