٩ الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤$b5$, '2024-10-13', 'active' FROM ins_art_alamiria_2024_161_4;
WITH ins_art_alamiria_2024_161_5 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 5, NULL, $b6$نظم الضبط الداخلى
يجب على المخاطبين بأحكام هذا القرار إعداد دليل عمل داخلى يتـضمن الـنظم
والإجراءات المتبعة لضمان التطبيق السليم للقواعد والضوابط والإجراءات ذات الصلة
بمكافحة غسل الأموال وتمويل الإرهاب ،مع مراعاة أحكام القانون ولائحته التنفيذية ،
على أن يتم مراجعة هذا الدليل بشكل دورى للوقوف على مدى تحديثه وتطويره واتخاذ
ما يلزم من إجراءات فى هذا الشأن ،ويجب أن يتضمن هذا الدليل على الأقل ما يلى :
 -١وضع إجراءات تفصيلية واضحة لمكافحة عمليات غسل الأمـوال وتمويـل
الإرهاب وإجراءات تفصيلية مكتوبة يراعى فيها التحديد الدقيق للواجبات والمسئوليات .
 -٢آليات التحقق من الالتزام بالنظم الداخلية الموضوعة لمكافحة عمليات غـسل
 الأموال وتمويل الإرهاب .
 -٣المتطلبات اللازمة لإدارة المخاطر المتعلقة بغسل الأموال وتمويل الإرهـاب
بشكل فعال بما فى ذلك الخبرات البشرية القادرة على التعامل مع هذه المخاطر والبنية
 التكنولوجية اللازمة لذلك .
 -٤نظم الضبط الداخلى المتبعة فى تحديد العمليات غير العاديـة ،أو العمـلاء
 المشتبه فيهم ،ووضعها تحت نظر مسئول مكافحة غسل الأموال وتمويل الإرهاب .
 -٥وضع إجراءات للكشف عن أسماء جميع العملاء والمستفيدين الحقيقيـين وأى
أطراف أخرى مطلوب الكشف عنهم على القوائم السلبية فى بدايـة التعامـل وبـشكل
 دورى واتخاذ الإجراءات اللازمة فى هذا الشأن .
 -٦وضع إجراءات داخلية للتحقق من الالتزام التام بأحكـام إجـراءات العنايـة
 الواجبة العملاء الصادرة عن الوحدة .
 -٧الالتزام بالتسجيل على الموقع الالكترونى للوحدة ومتابعة ما يرد من تحديثات
 ذات صلة بالقوائم السلبية أو أى ضوابط أو منشورات ذات صلة .
 -٨نظم تصنيف العملاء حسب درجة مخاطر غسل الأموال وتمويـل الإرهـاب
 وإدارة هذه المخاطر على أن يتم تحديثها بشكل دورى .
 ١٠الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤
 -٩وضع تدابير فعالة بما يضمن الحد من أية حـالات تواطـؤ بـين مـوظفى
الأشخاص الاعتبارية المخاطبة بأحكام هذا القرار وعملائها ،واكتشاف تلك الحـالات
 فور وقوعها .
 -١٠النظم التى تكفل قيام المراجع الداخلى أو لجان المراجعة ،بحسب الأحوال ،
بالتنسيق مع المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهـاب ،بفحـص
النظم الموضوعة للتأكد من كفاءتها وفعاليتها فى مكافحة عمليات غسل الأموال وتمويل
 الإرهاب ،واقتراح ما يلزم من إجراءات وقائية أو ما تحتاجه من تحديث وتطوير .
 -١١قواعد الاحتفاظ بالمستندات والـسجلات التـى يجـب علـى الأشـخاص
 الاعتبارية المخاطبين بأحكام هذا القرار إمساكها وتحديد طرق الاحتفاظ بها .
 -١٢وضع خطط وبرامج تدريب العاملين بهدف توعيتهم ورفع كفـاءتهم فيمـا
 يتعلق بالقواعد والنظم المقررة فى شأن مكافحة غسل الأموال وتمويل الإرهاب .
وفى جميع الأحوال ،يجب موافاة الهيئة بالدليل المـشار إليـه بـالفقرة الـسابقة
على أن يكون معتمدا من مجلس الإدارة بالنسبة للأشخاص الاعتبارية المخاطبة بأحكام
 هذا القرار .
كما يجب على المؤسسات المالية التى لها فروع وشركات تابعة خارج جمهوريـة
مصر العربية تطبيق ضوابط مكافحة غسل الأموال وتمويل الإرهاب بمـا يتفـق مـع
المتطلبات المفروضة داخلها ،مع مراعاة أنه فى حالة اختلاف تلـك الـضوابط عـن
المفروضة بالدولة التى بها الفرع أو الشركة التابعة يتم تطبيق الضوابط الأكثر تحفظ ًـا
 بما لا يتعارض مع التشريعات أو التعليمات الرقابية المطبقة بالدولة الأجنبية .$b6$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
