باللائحة التنفيذية لقانون مكافحة غسل الأموال ،وينبغى على المخاطبين بأحكـام هـذا
 القرار القيام بما يلى :
 -١الالتزام بالتعليمات التى تصدرها الوحدة بـشأن متطلبـات الإخطـار عـن
 العمليات المشتبه فيها .
 -٢موافاة الوحدة على الفور بأى بيانات أو معلومات تتاح لهم أو يتحصلوا عليها
تكون من شأنها تعزيز أو نفى كل أو بعض أسباب ودواعى الاشـتباه التـى اشـتملت
عليها إخطارات الاشتباه الذى سبق إرسالها للوحدة ،مع إرفـاق صـور المـستندات
 المؤيدة لها )إن وجدت( .
 -٣اتخاذ الإجراءات التى تضمن الاستفادة من التغذية العكسية التى يتلقوها مـن
الوحدة مما ينعكس إيجابا على إخطارات الاشتباه المرسلة للوحدة ونظـم وإجـراءات
 مكافحة غسل الأموال وتمويل الإرهاب لديهم .
 -٤أن يتوافر لديهم إجراءات ونظم تمكن العاملين لديهم من تحديد كافة العمليـات
التى يشتبه فى أنها تشكل متحصلات أو تتضمن غسل أموال أو تمويل إرهاب بما فـى
ذلك محاولات إجراء هذه العمليات ،بغض النظر عن قيمتهـا ،وتـضمن الإخطـار
الفورى داخليا للمدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب عـن تلـك
 العمليات من خلال قنوات واضحة ومؤمنة تمكن العاملين من ذلك .
 -٥أن يكون لديهم إجراءات ونظم تضمن سرعة فحص كافة تقـارير الاشـتباه
الداخلية ،وتضمن توفير التغذية العكسية والإرشادات والتعليمات بشأنها لرفع جودتها .
 -٦التقييم الدورى للإجراءات والنظم المشار إليها فى البند السابق وقنوات تلقـى
تقارير الاشتباه الداخلية للإخطار الفورى عنها وسرعة فحصها وتوفير التغذية العكسية
والإرشادات والتعليمات بشأنها ،واتخاذ ما يلزم على وجه الـسرعة لزيـادة فعاليتهـا
 وملاءمتها فى ضوء نتائج التقييم المشار إليه .
 -٧إعداد تقرير إحصائى نصف سنوى يتضمن بيان عدد حالات الاشتباه التى تم
إحالتها للوحدة على النحو المشار إليه ،على أن يتم موافاة الهيئة بذلك التقرير خـلال
 أسبوع من تاريخ انتهاء المدة المقدم عنها التقرير .
 ١٢الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤
وفى جميع الأحوال ،يحظر الإفصاح بشكل مباشـر أو غيـر مباشـر للعميـل
أو المستفيد أو لغير السلطات والجهات المختصة بتطبيق أحكام القانون -فـى حـدود
الاختصاصات المنصوص عليها قانون ًا -عن أى عمليات يشتبه فى أنها ت ُمثل جريمـة
غسل أموال أو تمويل إرهاب ،أو عن البيانات أو المعلومات أو المـستندات المتعلقـة
 بها أو أى إجراءات متخذة بشأنها .$b7$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b7$إجراءات الإخطار عن العمليات المشتبه فيها
يتعين على المخاطبين بأحكام هذا القرار إخطار الوحدة فورا عن أى من العمليات
التى يشتبه فى أنها تشكل متحصلات أو تتضمن غسل أمـوال أو تمويـل إرهـاب ،
أو محاولات إجراء هذه العمليات أيا كانت قيمتها وذلك بما لا يجاوز المـدة المقـررة
