WITH ins_art_alamiria_2024_161_7 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 7, NULL, $b8$التدريب فى مجال مكافحة غسل الأموال وتمويل الإرهاب
يتعين على المخاطبين بأحكام هذا القرار وضع الخطط والبرامج اللازمة لتـدريب
العاملين فيها مرة على الأقل كل سنة بهدف توعيتهم ورفع كفاءتهم فيما يتعلق بتطبيـق
القواعد والنظم المقررة فى شأن مكافحة غسل الأموال وتمويل الإرهاب ،بما يـضمن
اطلاعهم على التطورات الحديثة المتعلقة بالأساليب والاتجاهات العامة لعمليات غـسل
الأموال وتمويل الإرهاب ونظم مكافحتها ،والمستجدات المحلية والإقليميـة والعالميـة
فى هذا الشأن ،ويكون وضع هذه الخطط والبرامج وتنفيذها من خلال التنسيق مع كـل
 من الوحدة والهيئة ،مع مراعاة الآتى :
 -١أن يكون التدريب شاملا ً لكافة العاملين وكذا العاملين بالشركات التابعة بشكل
يكفل إعدادهم لحسن القيام بالاختصاصات الموكلة إليهم ومـسايرة التطـور العـالمى
 وترسيخ قواعد العمل المهنى السليم .
 -٢الاستفادة من البرامج التدريبية التى يقدمها معهد الخدمات المالية التابع للهيئـة
وغيره من المعاهد والمراكز المتخصصة داخليا أو خارجيا فيما يتعلق بمكافحة غـسل
الأموال وتمويل الإرهاب ،ويكون ذلك فى إطار السياسة العامة للتأهيل والتدريب التى
 تضعها الوحدة والهيئة .
 - ٣التنسيق مع المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب فيما
 يتعلق باختيار العاملين الذين يتم ترشيحهم لحضور برامج تدريبية فى هذا المجال .
الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ١٣ ٢٠٢٤$b8$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
