الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ١٣ ٢٠٢٤$b8$, '2024-10-13', 'active' FROM ins_art_alamiria_2024_161_7;
WITH ins_art_alamiria_2024_161_8 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 8, NULL, $b9$الاحتفاظ بالسجلات والمستندات
 يتعين على المخاطبين بأحكام هذا القرار الاحتفاظ بالسجلات والمستندات الآتية :
 -١السجلات والمستندات الخاصة بالتعرف على هويـة العمـلاء والمـستفيدين
الحقيقيين والتحقق منها ،على أن تتضمن كافة البيانات والمعلومـات المتعلقـة بهـم ،
ومنها عقود فتح الحساب وعقود تقديم الخدمات المالية غير المصرفية وما يتعلق بهـذه
العقود من أوراق ومستندات أخرى وعلى وجـه الخـصوص المـستندات الخاصـة
بالمطابقة التى تم إجرائها بشأن القوائم المعدة فى شأن الكيانات الإرهابية والإرهـابيين
سواء عند فتح الحساب أو بدء التعاقد أو عند تحـديث تلـك القـوائم ،وكـذا صـور
مستندات تحقيق الشخصية والمراسلات التى تتم مع العميل والمستندات الدالـة علـى
الإنابة فى التعامل للأشخاص المصرح لهم بالتعامل نيابة عن العملاء على أن تتـضمن
 بيانات كافية للتعرف على تفاصيل كل عملية على حدة .
 -٢السجلات والمستندات الخاصة بالعمليات غير العادية والعمليات المشتبه فيهـا
الواردة من العاملين داخليا ،على أن تتضمن ما يفيد مراجعة هذه العمليـات واتخـاذ
 قرار بشأنها ،وما قد يكون تم حفظه منها والأسباب التى تم الاستناد إليها فى الحفظ .
 -٣التقارير الدورية السنوية التى تم موافاة الوحدة والهيئة بها بشأن تقيـيم نظـم
 وإجراءات مكافحة غسل الأموال وتمويل الإرهاب .
 -٤السجلات الخاصة بالعمليات المشتبه فيها التى تم إرسالها إلى الوحدة على أن
تتضمن صور الإخطارات المرسلة للوحـدة عـن تلـك العمليـات وكافـة البيانـات
 والمستندات المتعلقة بها .
 -٥السجلات والمستندات الخاصة بالبرامج التدريبية على أن تشتمل على بيانات
كافة البرامج فى مجال مكافحة غسل الأموال وتمويل الإرهاب التـى يحـصل عليهـا
العاملين ،وأسماء المتدربين ،والأقسام أو الإدارات التى يعملـون بهـا ،ومحتـوى
البرنامج التدريبى ،وتاريخ انعقادها ومدتها ،والجهة التى قامت بالتدريب سواء كانـت
 بالداخل أو الخارج .
 ١٤الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤
 -٦السجلات الخاصة بالكشف على القوائم السلبية .
 -٧السجلات الخاصـة بالتجميـد ورفـع التجميـد عـن العمـلاء المـدرجين
 بالقوائم السلبية .
 -٨السجلات والمستندات الخاصة بالإحصائيات عن حجم الأموال أو الأصـول
 التى تم تجميدها أو مصادرتها ،وكذا التى تم رفع التجميد عنها .$b9$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
