 -٥السجلات والمستندات الخاصة بالبرامج التدريبية على أن تشتمل على بيانات
كافة البرامج فى مجال مكافحة غسل الأموال وتمويل الإرهاب التـى يحـصل عليهـا
العاملين ،وأسماء المتدربين ،والأقسام أو الإدارات التى يعملـون بهـا ،ومحتـوى
البرنامج التدريبى ،وتاريخ انعقادها ومدتها ،والجهة التى قامت بالتدريب سواء كانـت
 بالداخل أو الخارج .
 ١٤الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤
 -٦السجلات الخاصة بالكشف على القوائم السلبية .
 -٧السجلات الخاصـة بالتجميـد ورفـع التجميـد عـن العمـلاء المـدرجين
 بالقوائم السلبية .
 -٨السجلات والمستندات الخاصة بالإحصائيات عن حجم الأموال أو الأصـول
 التى تم تجميدها أو مصادرتها ،وكذا التى تم رفع التجميد عنها .$b9$, '2024-10-13', 'active' FROM ins_art_alamiria_2024_161_8;
WITH ins_art_alamiria_2024_161_9 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 9, NULL, $b10$الشروط الواجب إتباعها لدى الاحتفاظ بالسجلات والمستندات
يكون الاحتفاظ بالسجلات والمستندات على النحو المشار إليـه بالمـادة الـسابقة
بشكل يسير وسهل بما يساعد على سرعة استرجاع البيانات الواردة بتلـك الـسجلات
أو المستندات وتوفير البيانات والمعلومات التى يتم طلبها بـشكل وافٍ ودون تـأخير،
على أن يكون الاحتفاظ بكافة السجلات والمستندات بشكل ورقى أو إلكترونى بطريقـة
آمنة وأن يتم الاحتفاظ بنسخ احتياطية من هذه السجلات والمستندات فى مكـان آخـر
مؤمن ،كما ينبغى أن تتضمن إجراءات ونظم حفظ الـسجلات والمـستندات تحديـد
 صلاحيات الأشخاص المعنيين بالإطلاع عليها .
 ويكون الاحتفاظ بالسجلات والمستندات وفق ًا للمدد الآتية :
 ) أ( السجلات والمستندات الخاصة بالتعرف على هوية العميل والمستفيدين الحقيقيين :
 خمس سنوات على الأقل من تاريخ انتهاء العلاقة مع العميل .
)ب( السجلات والمستندات والتقارير الخاصة بالعمليات غير العادية التى تتم مع العملاء :
خمس سنوات على الأقل من تاريخ انتهاء العلاقة مع العميل أو تاريخ اتخاذ
 قرار بالحفظ أيهما أقرب .
 )ج( سجلات التدريب :
 خمس سنوات على الأقل من تاريخ انتهاء التدريب .
 )د( السجلات والمستندات الخاصة بالعمليات المشتبه فيها :
خمس سنوات على الأقل من تاريخ إرسال العملية المشتبه فيها إلى الوحدة
 أو لحين صدور قرار أو حكم نهائى فى شأن العملية أيهما أطول .
الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ١٥ ٢٠٢٤
 )هـ( التقارير الدورية السنوية التى يعدها مسئول مكافحة غسل الأموال وتمويل الإرهاب:
 خمس سنوات على الأقل من تاريخ اعتماد هذه التقارير .
 )و( السجلات الخاصة بالكشف على العملاء بالقوائم السلبية :
 خمس سنوات من تاريخ الكشف .
 )ز( السجلات الخاصة بالتجميد ورفع التجميد للعملاء المدرجين بالقوائم السلبية :
خمس سنوات من تاريخ صدور قرار التجميد أو رفع التجميد أو صدور حكم
 نهائى فى شأن التجميد من عدمه أيهما أطول .$b10$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
