WITH ins_art_alamiria_2024_161_10 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 10, NULL, $b11$التزامات مسئول المراجعة الداخلية
يجب على مسئول المراجعة الداخلية ) أو الوحـدة التنظيميـة المكلفـة بأعمـال
المراجعة الداخلية( بالجهات المخاطبة بهذا القرار إعداد تقرير دورى كل سنة ميلاديـة
للعرض على مجلس إدارة الجهة بشأن نتائج أعمال مسئول مكافحـة غـسل الأمـوال
وتمويل الإرهاب ،أخذ ًا فى الاعتبار طبيعة النشاط الـذى تزاولـه وحجمـه ونوعيـة
العملاء والمنتجات أو الخدمات المقدمة والتأكد بـشكل مـستمر مـن الالتـزام التـام
 بالمتطلبات القانونية والإجراءات التنظيمية الصادرة فى هذا الشأن .
ويتم إعداد التقرير خلال خمسة عشر يوما من انتهاء الفترة المقدم عنها التقريـر
ورفعه لمجلس إدارة الجهة للاعتماد ،ويجب موافاة الهيئة بهذا التقرير بعـد اعتمـاده
من مجلس إدارة الجهة خلال خمسة وأربعين يوما من انتهاء الفتـرة المـشار إليهـا ،
 مرفق ًا به تقرير المراجع الخارجى المشار إليه بالمادة الحادية عشرة من هذا القرار .
وفى جميع الأحوال ،يلتزم مسئول المراجعة الداخلية بموافاة الهيئة ومجلس إدارة
الجهة بأى أمور قد يكون من شأنها التأثير على متطلبـات مكافحـة غـسل الأمـوال
 وتمويل الإرهاب وذلك فور حدوثها .
 ١٦الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤$b11$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
