 ١٦الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤$b11$, '2024-10-13', 'active' FROM ins_art_alamiria_2024_161_10;
WITH ins_art_alamiria_2024_161_11 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 11, NULL, $b12$التزامات المراجع الخارجى
مع عدم الإخلال بأحكام التشريعات السارية فى شـأن المـراجعين الخـارجيين ،
يتعين على الجهات المخاطبة بأحكام هذا القرار تكليف مراقـب حـساباتها أو مراقـب
حسابات خارجى من المقيدين بسجل مراقبى الحسابات لدى الهيئة بالاطلاع على بيئـة
الرقابة الداخلية بالجهة وتقرير مسئول المراجعة الداخلية المشار إليه بالمادة الـسابقة ،
والتأكد من التزامها بالقواعد والتعليمات الرقابية الصادرة فـى شـأن مكافحـة غـسل
الأموال وتمويل الإرهاب وتمويل انتشار أسلحة الدمار الشامل ،ويلتزم بإعداد تقريـر
سنوى بشأن ما تم من إجراءات فى هذا الشأن على أن يقدمه للهيئـة والجهـة خـلال
خمسة وأربعين يوما من تاريخ انتهاء المدة المقدم عنها التقرير ،ويجـب أن يتـضمن
 التقرير على وجه الأخص مدى التزام الجهة بما يلى :
 -١تضمين دليل العمل الداخلى والنظم المطبقة بالجهة ضـوابط التعـرف علـى
الهوية والأوضاع القانونية للعملاء والمستفيدين الحقيقيين مـن الأشـخاص الطبيعيـين
 والأشخاص الاعتبارية والترتيبات القانونية الأخرى .
 -٢تعيين مسئول مكافحة غسل الأموال وتمويل الإرهاب ومـن يحـل محلـه ،
 والبيانات الخاصة بهم .
 -٣بيانات تصنيف العملاء وفق ًا لدرجة المخاطر .
 -٤موقف الجهة من تحديث بيانات العملاء .
 -٥إمساك السجلات التى يجب عليها الاحتفاظ بها وفق ًـا للتـشريعات الـصادرة
 فى هذا الشأن ،وكذا تحديث محتواها وبياناتها .
 -٦تحديث المادة التدريبية اللازمة لتدريب العاملين بالجهة بما يضمن اطلاعهـم
على التطورات الحديثة المتعلقة بالأساليب والاتجاهات العامة لعمليات مكافحـة غـسل
الأموال وتمويل الإرهاب وتمويل انتشار أسلحة الدمار الشامل ،والمستجدات المحليـة
الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ١٧ ٢٠٢٤
والإقليمية والعالمية فى هذا الشأن ،وكذا موقف الجهة من تطبيق خطة التدريب التـى
 تناسب عدد العاملين بها وبفروعها .
 -٧موافاة الوحدة والهيئة بالتقارير الدورية التى تلتزم بها فى مجال مكافحة غسل
 الأموال وتمويل الإرهاب .$b12$
  FROM laws WHERE law_no = 161 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
