WITH ins_art_alamiria_2024_161_12 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 12, NULL, $b13$المؤشرات الاسترشادية للتعرف على العمليات المشتبه فيها
على المخاطبين بأحكام هذا القـرار مراعـاة المؤشـرات الاسترشـادية الآتيـة
بحد أدنى عند التعرف على العمليـات المـشتبه فـى أنهـا تتـضمن غـسل أمـوال
 أو تمويل إرهاب :
 مؤشرات عامة لكافة الأنشطة :
 -١العملاء الذين يمتنعون عن توفير معلومات كافيـة ،أو يقـدمون معلومـات
غير صحيحة ،سواء كانت شخصية أو عن النـشاط أو عـن المـستفيدين الحقيقيـين
من التعامل على الحساب ،أو يمتنعون عن التوقيع علـى نمـوذج اعـرف عميلـك
أو التردد فى الإدلاء بالبيانات التفصيلية الواردة به ،أو عدم قـدرتهم علـى تجديـد
 سريان بطاقة الرقم القومى .
 -٢العملاء الذين يقومون بتقديم وثائق هوية بها شبهة تزوير .
 -٣العملاء الذين يواجهون صعوبة فى وصف طبيعة نشاطهم أو يفتقـرون إلـى
 المعلومات العامة فيما يتعلق بذلك النشاط .
