 مؤشرات خاصة بأنشطة الأوراق المالية :
 -١عمليات تغذية الحساب بمبالغ كبيرة ثم سحبها دون إتمام أية عمليـات ودون
 وجود مبرر واضح من العميل .
 -٢العمليات التى تتم بمبالغ كبيرة بما لا يتناسب مع نشاط العميل أو مستوى دخله .
 -٣اتجاه العميل نحو العمليات أو الصفقات التـى تـشير إلـى افتقـاره للحـس
الاستثمارى ،وعلى سبيل المثال عدم الاهتمام بالحصول على أفـضل سـعر للورقـة
 المالية المتعامل عليها بيعا وشراء. 
 -٤العملاء الذين يبدون لا مبالاة تجاه المخاطر أو العمـولات أو غيرهـا مـن
 تكاليف العمليات على الأوراق المالية .
 -٥تكرار طلبات تحويل مبالغ من حساب العميل إلى حسابات أخـرى بالـشركة
 دون مبرر واضح .
 -٦العمليات المتكررة التى لا يتناسب مجموعها خلال فترة زمنيـة معينـة مـع
 نشاط العميل .
 -٧عدم اهتمام العميل فى معظم الأحيان بما تقدمه الشركة من نصائح استثمارية .
 -٨العمليات التى يتم تمويلها عن طريق شيكات مصرفية أو أيـة أدوات ماليـة
 قابلة للتداول بصفة متكررة ودون مبرر واضح .
 -٩تعمد العميل القيام بعمليات متعددة تقل قيمتها عن الحد المقرر من قبل الهيئـة
 للسماح بالتعامل النقدى وذلك بقصد تجنب التعامل من خلال البنوك .
 مؤشرات خاصة بالتأمين :
