 -٧التعاقد على وثيقة بقسط وحيد أو بمبلغ كبير بما يخـالف نمـط التعـاملات
 السابقة للعميل .
 -٨طلب العميل زيادة قيمة وثيقة التأمين بمبلغ كبير يسدد على دفعة واحدة .
 -٩التعاقد على وثائق بمبالغ كبيرة وطلب استردادها أو تغيير المستفيد بعد فتـرة
 قصيرة من التعاقد دون مبرر واضح .
 -١٠طلب العميل اقتراض الحد الأقصى من قيمة وثيقة ذات قسط وحيد بعد فترة
 قصيرة من التعاقد وسداد قيمتها دون مبرر واضح .
 -١١سداد قيمة أو أقساط وثيقة التأمين بواسطة تحويلات مـن أطـراف أجنبيـة
 أو طلب استرداد وتحويل قيمتها لأطراف أجنبية .
 -١٢تغيير المستفيدين المحددين فى وثيقة التأمين بحيث يتم تـضمنين أشـخاص
 لا يوجد لهم صلة واضحة بالعميل ودون مبرر واضح .
 -١٣طلب الاسترداد المبكر لقيمة الوثيقة أو تغيير تاريخ استحقاقها ،وبخاصـة
 عندما يؤدى ذلك إلى تحمل خسائر مادية دون مبرر واضح .
 مؤشرات خاصة بالتمويل العقارى :
