بالجهات العاملة فى مجال الأنشطة المالية غير المصرفية بمهام وظيفته أو مخالفته
لأى من القوانين أو القواعد المنظمة لعمله أو فى حال فقده لأحد شروط قيده بالسجل،
 وبعد التحقيق معه ،أن يتخذ ما يراه مناسبا من التدابير الآتية:
 -١التنبيه.
 -٢الإنذار.
 -٣شطب القيد من السجل ،مع عدم جواز إعادة القيد إلا بعد انقضاء فترة لا تقل
 عن سنة ولا تزيد على ثلاث سنوات.
 -٤إلغاء الترخيص وشطب القيد من السجل مع عدم جواز إعادة الترخيص
 والقيد مرة أخرى.
 ) المادة الحادية والعشرون (
 التزامات المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب
 يلتزم المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب بالمهام الآتية:
 -١فحص العمليات غير العادية التى تستخرج من الأنظمة الداخلية للمؤسسات
المالية ،والعمليات الواردة بتقارير الاشتباه الداخلية ،والعمليات التى أثير الاشتباه فيها
 بناء على معلومات وردت من أية جهة أخرى أو معلومات نمت إلى عمله.
 -٢إخطار الوحدة بالعمليات التى يشتبه فى أنها تشكل متحصلات أو تتضمن
غسل أموال أو تمويل إرهاب ،بما فى ذلك محاولات إجراء هذه العمليات ،بغض
 النظر عن قيمتها وبالشكل الذى يكفل الحفاظ على سرية المعلومات بها.
 -٣اتخاذ القرارات بشأن حفظ العمليات التى تم فحصها وتبين له عدم وجود أية
 شبهة بشأنها على أن يتضمن القرار الأسباب التى استند إليها فى الحفظ.
 -٤اقتراح ما يراه لازما من تطوير وتحديث للسياسة المتبعة فى الجهة التى
يعمل بها بشأن مجال مكافحة غسل الأموال وتمويل الإرهاب وكذا النظم والإجراءات
المتبعة بها فى هذا المجال وذلك بهدف زيادة فاعليتها وكفاءتها ومواكبتها المستجدات
 المحلية والعالمية.
 ٣٠الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤
 -٥الإشراف العام مكتبيا وميدانيا ،بنفسه أو من خلال الاستعانة بالإدارات
بالجهة التى يعمل بها للتأكد من مدى التزام المركز الرئيسى لها وفروعها بتطبيق
أحكام القانون ولائحته التنفيذية والقواعد والضوابط الرقابية ذات الصلة بمكافحة غسل
 الأموال وتمويل الإرهاب والنظم والإجراءات الداخلية الموضوعة فى هذا الشأن .
 -٦التعاون والتنسيق مع الإدارات المعينة بالجهة التى يعمل بها فى شأن وضع
خطط التدريب الداخلية والخارجية فى مجال مكافحة غسل الأموال وتمويل الإرهاب
 للعاملين بها ،واقتراح البرامج التدريبية اللازمة لتنفيذ هذه الخطط ،ومتابعة التنفيذ.
 -٧التسجيل على موقع الوحدة لاستلام التحديثات الخاصة بالتعديلات على قوائم
 مجلس الأمن وقائمتى الكيانات الإرهابية والإرهابيين المحلية.
 -٨متابعة الموقع الإلكترونى للوحدة بصفة يومية لتعميم أى تحديث قد يطرأ
على قوائم العقوبات المالية المستهدفة أو أى إرشادات أو إجراءات محدثة يتم إصدارها
 من الوحدة ،وذلك دون انتظار ورود أى إخطار أو تعميم من الهيئة فى هذا الشأن .
 -٩متابعة التزام الجهة وفروعها بالرجوع إلى القوائم السلبية عند إجراء أى
عملية أو الدخول فى علاقة عمل جديدة مع شخص أو جهة للتأكد من الإدراج على
 تلك القوائم من عدمه .
 -١٠التحديث الفورى للمعلومات المتعلقة بالقوائم الـسببية ومـا يطـرأ عليهـا
 من تعديلات.
 -١١فحص ومطابقة كافة العملاء الحاليين للجهة عند إجراء كل تحديث للقوائم
 السلبية للتأكد من عدم وجودهم ضمن عملاء الجهة وحظر التعامل معهم.
 -١٢التأكد من عدم التعامل مع أى شخص طبيعى أو اعتبارى من الأسماء المدرجة
 بالقوائم السلبية والتى يتم مراجعتها بشكل يومى ،ويتم التحقق فى الحالات الآتية :
)أ( مراجعة أسماء العملاء الجدد وتحديد المستفيد الفعلى فى حال بدء علاقة عمل
مع العميل قبل القيام بإجراءات فتح الحساب أو الحصول علـى تمويـل أو
وثائق تأمين بحسب الأحوال ،بحيث يتم مراجعة كافة الأطـراف المتعاملـة
على الحساب والمتمثلة فى )العميل ،المـساهم ،الـضامن ،المـرخص لـه
بالتوقيع ،الشريك ،الوكيل ،الولى ،الوصى ...إلخ( أو أى أطراف أخـرى
 متعاملة على حساب العميل.
 )ب( عند تحديث العملاء القائمين لبياناتهم.
الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٣١ ٢٠٢٤
 -١٣متابعة إجراءات تطبيق العقوبات المالية المستهدفة دون تأخير وما يتبع ذلك
 من إجراءات التجميد الفورى ورفع التجميد وإخطار الوحدة والهيئة بذلك.
 -١٤مراجعة الأنظمة المطبقة للكشف بالقوائم وفق ًا للنظم المعمول بها بكل جهة،
 والتأكد من دورية التحديث الذى يتم على هذه القوائم.
 -١٥التأكد من تعميم إجراءات العناية الواجبة بالعملاء على كافة فروع الجهة.
 -١٦الاحتفاظ بالمستندات الدالة على قيام الجهة بالكشف عن عملائها بالقوائم
السلبية سواء قوائم عقوبات مجلس الأمن ذات الصلة بالإرهاب وتمويله وتمويل انتشار
 أسلحة الدمار الشامل أو قائمتى الكيانات الإرهابية والإرهابيين.
 -١٧إعداد تقرير دورى مرة على الأقل كل سنة عن أوجه نشاطه وتقييمه لنظم
وإجراءات مكافحة غسل الأموال وتمويل الإرهاب فى الجهة التى يعمل بها ،وعن
العمليات غير العادية والمشتبه فيها وما اتخذ فى شأنها من إجراءات مشفوعا بما يراه
من اقتراحات فى هذا الشأن ،ويقدم التقرير إلى مجلس إدارة الجهة لإبداء ما يراه من
ملاحظات وما يقرر اتخاذه من إجراءات فى شأنه ،على أن يرسل هذا التقرير إلى
الوحدة والهيئة مشفوعا بملاحظات وقرارات مجلس إدارة الجهة فى شأنه فى موعد
أقصاه نهاية شهر يناير من العام التالى للفترة المعد عنها التقرير وذلك وفق ًا للنموذج
 المعد من الوحدة فى هذا الشأن .
 -١٨إمداد الوحدة بما تطلبه من المعلومات والبيانات والإحصائيات اللازمة
لمباشرتها لاختصاصاتها ،وتيسير الاطلاع على السجلات والمستندات فى سبيل مباشرتها
أعمال التحرى والفحص أو لتضمينها قاعدة البيانات المنشأة فى الوحدة ،كما يلتزم بموافاة
الهيئة بأى من البيانات أو الإحصائيات اللازمة فى هذا الشأن ،وذلك دون الإخلال
 بالقوانين المنظمة للأنشطة المالية غير المصرفية .
 -١٩توفير التغذية العكسية والإرشادات والتعليمات بشأن تقارير الاشتباه الداخلية
 لرفع جودتها .
ويلتزم الأشخاص الطبيعيون المرخص لهم بمزاولة أى أعمال تتصل بأحد الأنشطة
المالية غير المصرفية على النحو الوارد بالقوانين المنظمة لها ،بالقيام بمهام المدير
 المسئول عن مكافحة غسل الأموال وتمويل الإرهاب المشار إليها بهذه المادة .
 ٣٢الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٢٠٢٤
 ) المادة الثانية والعشرون (
 ضمانات وصلاحيات مسئول مكافحة غسل الأموال وتمويل الإرهاب
يجب أن يتمتع المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب
بالاستقلال فى أداء مهامه وأن يتاح له كافة الوسائل الكفيلة للقيام بهذه المهام على نحو
 يحقق الغرض منها ،ويستلزم ذلك ما يلى :
 -١الالتزام بعدم إسناد أى أعمال إليه تتعارض مع مهامه باعتباره مسئولا ً عن
 مكافحة غسل الأموال وتمويل الإرهاب .
 -٢أن يكون له الحق فى الحصول على كافة المعلومات والاطلاع على كافة
السجلات أو المستندات التى يراها لازمة لمباشرة مهامه فى فحص تقارير العمليات غير
العادية وحالات الاشتباه التى ترد إليه ،والاتصال بمن يلزم من العاملين بالجهة التى يعمل
 بها لتنفيذ تلك المهام .
 -٣أن يكون له الحق فى تقديم تقارير إلى الإدارة العليا بالجهة التى يعمل بها أو إلى
