 التزامات المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب
 يلتزم المدير المسئول عن مكافحة غسل الأموال وتمويل الإرهاب بالمهام الآتية:
 -١فحص العمليات غير العادية التى تستخرج من الأنظمة الداخلية للمؤسسات
المالية ،والعمليات الواردة بتقارير الاشتباه الداخلية ،والعمليات التى أثير الاشتباه فيها
 بناء على معلومات وردت من أية جهة أخرى أو معلومات نمت إلى عمله.
 -٢إخطار الوحدة بالعمليات التى يشتبه فى أنها تشكل متحصلات أو تتضمن
غسل أموال أو تمويل إرهاب ،بما فى ذلك محاولات إجراء هذه العمليات ،بغض
 النظر عن قيمتها وبالشكل الذى يكفل الحفاظ على سرية المعلومات بها.
 -٣اتخاذ القرارات بشأن حفظ العمليات التى تم فحصها وتبين له عدم وجود أية
 شبهة بشأنها على أن يتضمن القرار الأسباب التى استند إليها فى الحفظ.
 -٤اقتراح ما يراه لازما من تطوير وتحديث للسياسة المتبعة فى الجهة التى
يعمل بها بشأن مجال مكافحة غسل الأموال وتمويل الإرهاب وكذا النظم والإجراءات
المتبعة بها فى هذا المجال وذلك بهدف زيادة فاعليتها وكفاءتها ومواكبتها المستجدات
 المحلية والعالمية.
