أحكام القانون ولائحته التنفيذية والقواعد والضوابط الرقابية ذات الصلة بمكافحة غسل
 الأموال وتمويل الإرهاب والنظم والإجراءات الداخلية الموضوعة فى هذا الشأن .
 -٦التعاون والتنسيق مع الإدارات المعينة بالجهة التى يعمل بها فى شأن وضع
