 -١٣متابعة إجراءات تطبيق العقوبات المالية المستهدفة دون تأخير وما يتبع ذلك
 من إجراءات التجميد الفورى ورفع التجميد وإخطار الوحدة والهيئة بذلك.
 -١٤مراجعة الأنظمة المطبقة للكشف بالقوائم وفق ًا للنظم المعمول بها بكل جهة،
 والتأكد من دورية التحديث الذى يتم على هذه القوائم.
 -١٥التأكد من تعميم إجراءات العناية الواجبة بالعملاء على كافة فروع الجهة.
 -١٦الاحتفاظ بالمستندات الدالة على قيام الجهة بالكشف عن عملائها بالقوائم
السلبية سواء قوائم عقوبات مجلس الأمن ذات الصلة بالإرهاب وتمويله وتمويل انتشار
 أسلحة الدمار الشامل أو قائمتى الكيانات الإرهابية والإرهابيين.
 -١٧إعداد تقرير دورى مرة على الأقل كل سنة عن أوجه نشاطه وتقييمه لنظم
وإجراءات مكافحة غسل الأموال وتمويل الإرهاب فى الجهة التى يعمل بها ،وعن
العمليات غير العادية والمشتبه فيها وما اتخذ فى شأنها من إجراءات مشفوعا بما يراه
من اقتراحات فى هذا الشأن ،ويقدم التقرير إلى مجلس إدارة الجهة لإبداء ما يراه من
ملاحظات وما يقرر اتخاذه من إجراءات فى شأنه ،على أن يرسل هذا التقرير إلى
الوحدة والهيئة مشفوعا بملاحظات وقرارات مجلس إدارة الجهة فى شأنه فى موعد
أقصاه نهاية شهر يناير من العام التالى للفترة المعد عنها التقرير وذلك وفق ًا للنموذج
 المعد من الوحدة فى هذا الشأن .
 -١٨إمداد الوحدة بما تطلبه من المعلومات والبيانات والإحصائيات اللازمة
