أعمال التحرى والفحص أو لتضمينها قاعدة البيانات المنشأة فى الوحدة ،كما يلتزم بموافاة
الهيئة بأى من البيانات أو الإحصائيات اللازمة فى هذا الشأن ،وذلك دون الإخلال
 بالقوانين المنظمة للأنشطة المالية غير المصرفية .
 -١٩توفير التغذية العكسية والإرشادات والتعليمات بشأن تقارير الاشتباه الداخلية
 لرفع جودتها .
ويلتزم الأشخاص الطبيعيون المرخص لهم بمزاولة أى أعمال تتصل بأحد الأنشطة
المالية غير المصرفية على النحو الوارد بالقوانين المنظمة لها ،بالقيام بمهام المدير
