مجلس الأمن ،ويقوم المجلس بمتابعة طلبات اقتراح أسماء جديدة للإدراج والمقدمة من
 الدول المختلفة وكذلك طلبات رفع الأسماء وطلبات الإعفاء من التجميد.
 -٢أصدرت مجموعة العمل المالى توصيتها السادسة بشأن إلزام الدول بتطبيق
أنظمة العقوبات المالية المستهدفة الصادرة بموجب الفصل السابع من ميثاق الأمم المتحدة
وفق ًا لقرارات مجلس الأمن وتحديدا تلك التى تتعلق بمنع وقمع الإرهاب وتمويله ومن أهم
تلك القرارات :القرارات أرقام ) (٢٢٥٣/١٩٨٩/١٢٦٧والقرارات اللاحقة له فيما يخص
العقوبات المتعلقة بالأشخاص والكيانات التابعة للقاعدة وداعش ،والقرار رقن )(١٩٨٨
فيما يخص الأشخاص والكيانات المتعلقة بحركة طالبان ،وتلزم تلك القرارات الدول بأن
تجمد دون تأخير الأموال أو الأصول أو الموارد الاقتصادية الخاصة بأى شخص أو كيان
 مدرج بموجب هذه القرارات .
 -٣أصدرت مجموعة العمل المالى توصيتها السابعة لتلزم الدول بتطبيق أنظمة
العقوبات المالية المستهدفة وفق ًا لقرارات مجلس الأمن التى تتعلق بمنع وقمع انتشار أسلحة
الدمار الشامل وتمويله ولاسيما القرار رقم ) (١٧١٨والقرارات اللاحقة له فيما يتعلق
بفرض الحظر على الأسلحة وتجميد الأصول وحظر السفر على الأشخاص المشاركين فى
البرنامج النووى لجمهورية كوريا الشعبية الديمقراطية ،والقرار رقم ) (٢٢٣١فى الشأن
الإيرانى والقرارات السابقة واللاحقة له ،وتلزم تلك القرارات الدول بأن تجمد دون تأخير
الأموال والأصول الأخرى التى تخص أى شخص أو كيان محدد من قبل مجلس الأمن
الوقائع المصریة – العدد ) ٢٢٥تابع ( فى ١٣أكتوبر سنة ٣٥ ٢٠٢٤
وأن تتأكد من عدم إتاحة أى أموال أو أصول أخرى بصورة مباشرة أو غير مباشرة له
 أو لصالحه أو لمنفعته.
 -٤أكد قرار مجلس الأمن رقم ) (١٣٧٣على ضرورة قيام الدول بالتصدى للأعمـال
الإرهابية والإرهابيين داخل حدود الدولة وخارجها ،وأشار إلى أن ذلـك يتطلـب وضـع
تدابير تضمن منع الأعمال الإرهابية وتجريمها ،وتجميـد الأمـوال والأصـول الأخـرى
الخاصة بالإرهابيين والكيانات الإرهابية ،وبناء عليه ،تم إصدار عدد من القـوانين لتحقيـق
التنفيذ الفعال لهذا القرار ،ومن أهمها قانون تنظيم قوائم الكيانات الإرهابيـة والإرهـابيين،
والذى تم بموجبه إعداد قائمتى الكيانات الإرهابية والإرهابيين ،وتحديد الآثار المترتبة علـى
إدراج أسماء أشخاص أو كيانات على أى من هاتين القائمتين ومن بينهـا تجميـد الأمـوال
 والأصول الأخرى.$b21$, '2024-10-13', 'active' FROM ins_art_alamiria_2024_161_20;

-- ===== 53-2018-ضوابط-منح-الترخيص-واستمراره-وقواعد-تملك-الاسهم-1 : قرار 53/2018 (مُهيكَل، 13 مادة) =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (53, 2018, $t22$قرار مجلس إدارة الهيئة رقم (53) لسنة 2018 بشأن ضوابط منح الترخيص واستمراره وقواعد تملك أسهم الشركات العاملة فى الأنشطة المالية غير المصرفية (وفقاً لآخر تعديل بتاريخ 2024/6/26)$t22$, $t22$قرار مجلس إدارة الهيئة رقم (53) لسنة 2018 بشأن ضوابط منح الترخيص واستمراره وقواعد تملك أسهم الشركات العاملة فى الأنشطة المالية غير المصرفية (وفقاً لآخر تعديل بتاريخ 2024/6/26)$t22$, 'aml_cft', 'in_force', $u22$https://fra.gov.eg/wp-content/uploads/2022/11/53-2018-ضوابط-منح-الترخيص-واستمراره-وقواعد-تملك-الاسهم-1.pdf$u22$, '2018-04-26')
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art_53_2018__________________________________1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $b23$تسري أحكام هذا القرار بشأن ضوابط منح الترخيص واستمراره للشركات العاملة في مجال األنشطة المالية غير المصرفية
 وقواعد تملك أسهمها.
 وال تسري األحكام الخاصة بهيكل الملكية أو إجراءات نقل ملكية األسهم الواردة بهذا القرار على البنوك الخاضعة إلشراف
 ورقابة البنك المركزي المصري التي يرخص لها بمباشرة أحد األنشطة المالية غير المصرفية أو شركات اإليداع والقيد
 المركزي لألوراق المالية.
 2$b23$
