WITH ins_art_53_2018__________________________________2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $b24$في تطبيق أحكام هذا القرار ،يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
الشركة العاملة في األنشطة هي الشركة المرخص لها من الهيئة بمزاولة أي من األنشطة المالية غير المصرفية ،ويشار إليها
 في أحكام هذا القرار بـ «الشركة العاملة». المالية غير المصرفية
المساهم المالك لنسبة %10فأكثر من رأس مال الشركة سواء بمفرده أو من خالل أطرافه المرتبطة. المساهم الرئيسي
يقصد باألطراف المرتبطة األشخاص الذين يجمع بينهم اتفاق بغرض االستحواذ أو السيطرة الفعلية األطراف المرتبطة
على إحدى الشركات الخاضعة ألحكام هذا القرار ،ويعد من بينهم األشخاص الطبيعية وأقاربهم حتى
الدرجة الثانية أو األشخاص االعتبارية إذا كانت تحت السيطرة الفعلية لذات األشخاص الطبيعية أو
االعتبارية ،وكذلك مجموع األشخاص الخاضعة للسيطرة الفعلية لذات األشخاص الطبيعية أو
االعتبارية أو الذي يكون بينهم اتفاق على ممارسة حقوقهم في الجمعية العامة أو مجلس إدارة
 الشركة بما يؤدي إلى السيطرة الفعلية على أي منهما.
 .1البنوك المصرية وفروع البنوك األجنبية الخاضعة إلشراف البنك المركزي المصري. المؤسسات المالية
 .2شركات التأمين أو إعادة التأمين.
 .3الشركات التي يكون غرضها االشتراك في تأسيس الشركات التي تصدر أوراق مالية أو
 زيادة رؤوس أموالها.
 .4الشركات والجهات التي تزاول نشاط البورصات.
 .5شركات الوساطة في السندات والمتعاملون الرئيسيون.
 .6شركات رأس المال المخاطر.
 .7شركات المقاصة واإليداع والقيد المركزي.
 .8شركات التمويل العقاري أو إعادة التمويل العقاري.
 .9شركات التأجير التمويلي أو التخصيم.
 .10شركات التمويل االستهالكي.
 .11شركات تمويل المشروعات المتوسطة والصغيرة و/أو متناهية الصغر.
 .12صناديق االستثمار.
 .13شركات االستثمار المباشر.
 2تم إضافة البندين 14،15بتعريف المؤسسات المالية بموجب قرار مجلس إدارة الهيئة رقم 143بتاريخ ،2018/9/13ثم تم استبدال (تعريف مصطلحات
 «الشركة العاملة في األنشطة المالية غير المصرفية "الشركة العاملة"»« ،المؤسسات المالية»« ،التملك غير المباشر» والواردة بالمادة الثانية ،).وإضافة تعريف
 جديد لمصطلح «المستثمر المؤهل» بموجب قرار مجلس إدارة الهيئة رقم 249بتاريخ .2023/11/29
 2
 .14الهيئة القومية للبريد.
 .15صناديق التأمين الخاصة التي تبلغ حجم أموالها المستثمرة أكثر من 100مليون جنيه.
 .16جهاز تنمية المشروعات المتوسطة والصغيرة ومتناهية الصغر.
 .17صندوق مصر السيادي لالستثمار والتنمية.
 .18صندوق مصر الفرعي للخدمات المالية والتحول الرقمي.
 .19الشركات أو الجهات من األشخاص االعتبارية العامة والخاصة الصادر بشأنها قرار من
 مجلس إدارة الهيئة.
 .20األشخاص االعتبارية األجنبية التي تمارس إحدى األنشطة المالية المصرفية أو غير
 المصرفية الخاضعة إلشراف ورقابة جهة تمارس اختصاصات مثيلة للبنك المركزي
 المصري أو الهيئة بحسب األحوال.
 .21المؤسسات المالية العربية واإلقليمية والدولية التي توافق عليها الهيئة.
الحاالت التي يتم فيها تملك أسهم أو السندات القابلة للتحويل إلي أسهم بالشركات العاملة وذلك باسم التملك المباشر
طالب التملك أو أطرافه المرتبطة ،ويدخل في حساب الملكية شهادات اإليداع األجنبية المقابلة ألسهم
 الشركات.
هي نسبة المساهمة ألحد األشخاص من خالل أطرافه المرتبطة في رأس مال الشركة المرخص لها التملك غير المباشر
 المستهدفة أفقيا ً أو رأسيا ً وصوالً للمستفيد النهائي.
 يقصد بالمستثمر المؤهل أي مما يلي: المستثمر المؤهل
أ) األشخاص الطبيعيون من ذوي الخبرة التي ال تقل عن عشر سنوات في مجال إدارة األموال
واستثمارها و /أو االستثمار المباشر و/أو المجاالت المرتبطة باألنشطة المالية المصرفية أو
غير المصرفية ،على أال تقل قيمة األصول السائلة أو األوراق أو األدوات المالية المملوكة له
 عن عشرة ماليين جنيه.
ب) الجهات الحكومية واألشخاص االعتبارية العامة وأجهزة الدولة التي تسمح القوانين والقرارات
 المنظمة لها بمزاولة أنشطة مالية واستثمارية بما فيها تأسيس الشركات أو المساهمة فيها.
 ج) شركات األموال التي ال يقل حقوق ملكيتها عن عشرة ماليين جنيه.
 د) المؤسسات المالية المشار إليها بهذا القرار.
هي إحدى الشركات التي يتم تأسيسها والترخيص لها كشركة رأس مال مخاطر ،وتكون ذات غرض الشركة ذات غرض
وحيد هو االستحواذ على شركات أخرى ،وتقوم بالحصول على التمويل الالزم للقيام بعمليات االستحواذ 3
 االستحواذ من خالل طرح زيادة رأس مالها في اكتتاب خاص.
