 تأسيس وترخيص الشركات العاملة يف األنشطة املالية غري املصرفية$b24$, '2018-04-26', 'active' FROM ins_art_53_2018__________________________________2;
WITH ins_art_53_2018__________________________________3 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 3, NULL, $b25$تكون الموافقة على طلبات تأسيس أو ترخيص الشركات العاملة في ضوء حاجة السوق للنشاط المطلوب الترخيص به أو
تأسيس شركة لمباشرته بنا ًء على دراسة للسوق تٌعتمد من مجلس إدارة الهيئة أو تقديم منتجات جديدة أو تطوير منتجات
 قائمة –بحسب األحوال ،-وبمراعاة توافر االشتراطات األخرى الواجب االلتزام بها وفقا ً التشريعات المنظمة لكل نشاط.
وبالنسبة للشركات ذات غرض االستحواذ فتلتزم بتقديم طلب قيد أسهمها بالبورصة خالل شهر من تاريخ حصولها على
الترخيص وإال اعتبر ترخيصها كأن لم يكن ،وفى حال شطب قيد أسهم الشركة من البورصة يتم إلغاء ترخيصها وتلتزم باتخاذ
 إجراءات التصفية ،وذلك ما لم تقدم الشركة مبررات تقبلها الهيئة4.
 5$b25$
  FROM laws WHERE law_no = 53 AND law_year = 2018
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b25$تكون الموافقة على طلبات تأسيس أو ترخيص الشركات العاملة في ضوء حاجة السوق للنشاط المطلوب الترخيص به أو
تأسيس شركة لمباشرته بنا ًء على دراسة للسوق تٌعتمد من مجلس إدارة الهيئة أو تقديم منتجات جديدة أو تطوير منتجات
 قائمة –بحسب األحوال ،-وبمراعاة توافر االشتراطات األخرى الواجب االلتزام بها وفقا ً التشريعات المنظمة لكل نشاط.
وبالنسبة للشركات ذات غرض االستحواذ فتلتزم بتقديم طلب قيد أسهمها بالبورصة خالل شهر من تاريخ حصولها على
الترخيص وإال اعتبر ترخيصها كأن لم يكن ،وفى حال شطب قيد أسهم الشركة من البورصة يتم إلغاء ترخيصها وتلتزم باتخاذ
 إجراءات التصفية ،وذلك ما لم تقدم الشركة مبررات تقبلها الهيئة4.
 5$b25$, '2018-04-26', 'active' FROM ins_art_53_2018__________________________________3;
WITH ins_art_53_2018__________________________________4 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 4, NULL, $b26$مع عدم اإلخالل بمتطلبات التأسيس أو الترخيص المطلوبة وفقا للتشريعات المنظمة لكل نشاط ،يجب على الشركات الراغبة
في الحصول على موافقة مبدئية على التأسيس أو الحصول على ترخيص بمزاولة أحد األنشطة المالية غير المصرفية،
 االلتزام بما يلي:
 -1تقديم دراسة الجدوى الفنية واالقتصادية للشركة وفقا ً للنموذج المعتمد من الهيئة.
 -2أال تقل نسبة مساهمة المؤسسة المالية عن ( )%25من رأس مال الشركة ،أو أال تقل نسبة مساهمة المستثمر
المؤهل عن ثلثي رأس مال الشركة ،مع االلتزام بالضوابط الخاصة بهيكل الملكية لبعض األنشطة المالية غير المصرفية
 على النحو الوارد بالجدول رقم ( )1المرفق بهذا القرار.
 -3اإلفصاح عن المستفيد النهائي للمساهمين وفقا ً لألحكام الواردة بالباب الثالث عشر من الالئحة التنفيذية لقانون سوق
 رأس المال.
 -4وجوب استخدام أسلوب التصويت التراكمي في انتخاب أعضاء مجلس اإلدارة بما يسمح بالتمثيل النسبي في عضوية
 مجلس اإلدارة كلما أمكن ذلك.
 -5أال يقل نسبة تمثيل المرأة في مجلس إدارة الشركة عن (.)%25
 -6االنتهاء من إجراءات التأسيس خالل فترة ال تزيد علي ستة أشهر من تاريخ موافقة الهيئة المبدئية ،ويجوز للهيئة
مدها لمدد أخرى بنا ًء على مبررات تقبلها الهيئة وبمراعاة التشريعات المنظمة لبعض األنشطة ،وفى حالة عدم إنهاء
 تأسيس الشركة في المدد المحددة تعتبر موافقة الهيئة المبدئية كأن لم تكن.
 -7استيفاء كافة متطلبات الحصول على الترخيص خالل ثالثة أشهر على األكثر من تاريخ القيد بالسجل التجاري ،ويجوز
مدها بنا ًء على مبررات تقبلها الهيئة ،وفى حالة تجاوز الشركة المدد المحددة للتقدم بمستندات الترخيص يجوز للهيئة
في ضوء حاجة السوق قبول الطلب بعد تحديث مستندات الشركة بما فيها تقديم دراسة جدوى فنية واقتصادية جديدة
واستيفاء كافة متطلبات الترخيص بمزاولة النشاط وفقا ً للضوابط المعمول بها وقت تقديم طلب الترخيص ،على أن
يكون من بينها توافر خبرة في القطاع المالي المصرفي و/أو غير المصرفي لدى نصف أعضاء مجلس إدارة الشركة
على األقل بخالف العضو المنتدب وذلك وفقا ً لمدد الخبرة المنصوص عليها بقرارات مجلس إدارة الهيئة الصادرة في
شأن كل نشاط ،ومع االلتزام بأن يكون ربع أعضاء مجلس إدارة شركات التأمين على األقل من ذوي الخبرة في مجال
 التأمين .وال تسري متطلبات الخبرة الواردة بهذا البند في شأن الشركات التي تقدم استشارات مهنية.
 - 4تم إضافة الفقرة الثانية بــ (المادة الثالثة) بموجب قرار مجلس إدارة الهيئة رقم 140بتاريخ .2024/6/26
 - 5تم استبدال نص المادة الرابعة بموجب قرار مجلس إدارة الهيئة رقم 249بتاريخ .2023/11/29
 4
 -8أن يتم بدء العمل في النشاط واالنتهاء من التجهيزات المطلوبة وتعيين فريق العمل بالخبرات المطلوبة وفقا ً لكل نشاط
والبدء الفعلي للنشاط خالل ستة أشهر على األكثر من تاريخ الحصول على الترخيص ،ويجوز مد هذه المدة في ضوء
المبررات التي تقدمها الشركة وتقبلها الهيئ ة ،وفي حالة عدم البدء الفعلي للنشاط في المدد المحددة يعتبر الترخيص
 ال غيا.
 -9استيفاء نموذج اإلفصاح المعد من الهيئة في شأن التحقق من مصادر أموال مؤسسي الشركة ومساهميها الرئيسيين.
 -10أال يكون أي من مؤسسي الشركة أو مساهميها الرئيسيين أو المستفيدين النهائيين أو أعضاء مجلس اإلدارة مدرجين
 في القوائم السلبية المتعلقة بالعقوبات المحلية أو الدولية.
 ويشترط أن يتوافر في الشخص االعتباري الذي يجوز له المشاركة في تأسيس الشركات العاملة ما يلي:
 أ -أال يكون في حالة إعسار مالي أو إفالس.
ب -أال تكون الهيئة قد اتخذت ضده أو أي من مساهميه الرئيسين أو أعضاء مجلس إدارته إجراءات تحريك الدعوي
الجنائية بشأن أحد الجرائم المنصوص عليها في القوانين والقواعد المنظمة لألنشطة المالية غير المصرفية أو
صدرت ضد أي منهم أحكام قضائية نهائية في أي من تلك الجرائم والجرائم المنصوص عليها بقانون البنك المركزي
والجهاز المصرفي أو قانون مكافحة غسل األموال خالل الثالث سنوات السابقة على طلب التأسيس ما لم يكن قد
تصالح عنها ،أو يكون قد صدر ضد أي منهم أحكام نهائية بعقوبة جنائية أو جنحة في جريمة مخلة بالشرف أو
 األمانة مالم رد إليه اعتباره.
ج -أال تكون الجهة اإلدارية التابع لها قد اتخذت ضده أي من التدابير االحترازية أو الجزاءات اإلدارية-باستثناء التنبيه
واإلنذار -خالل السنوات الثالث السابقة على طلب التأسيس مالم تكن قد ازيلت أسبابها ومرت ستة أشهر على تلك
 اإلزالة.
 كما تسري األحكام الواردة بالبنود السابقة على المستثمرين المؤهلين المشاركين في تأسيس الشركة العاملة.
وتلتزم الشركات الحاصلة على ترخيص بمزاولة أحد األنشطة المالية غير المصرفية بإخطار الهيئة قبل قيامها بإجراء أي
 تعديل في تشكيل مجالس إدارتها ،ويعد مضي أسبوعين دون رد من الهيئة بمثابة موافقة على إجراء هذا التعديل.$b26$
  FROM laws WHERE law_no = 53 AND law_year = 2018
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
