مع عدم اإلخالل بالمادة ( 27مكررا ً )1من قانون اإلشراف والرقابة على التأمين في مصر ،وكذا أحكام الباب الثاني عشر
من الالئحة التنفيذية لقانون سوق رأس المال والمادتين 328مكرراً 328 ،مكررا ً 1منه ،تسري األحكام التالية بشأن
ضوابط تملك الشخص الطبيعي أو االعتباري -بطريق مباشر أو غير مباشر سواء بمفرده أو من خالل مجموعة مرتبطة -
 في رأسمال أو حقوق التصويت بأي شركة من الشركات العاملة.$b27$, '2018-04-26', 'active' FROM ins_art_53_2018__________________________________5;
WITH ins_art_53_2018__________________________________6 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 6, NULL, $b28$على كل شخص طبيعي أو اعتباري يمتلك %5من رأس مال أو حقوق التصويت إلحدى الشركات العاملة أن يخطر الهيئة
 بذلك خالل أسبوعين من تاريخ تملكه لهذه النسبة.
ويحظر على أي شخص طبيعي – بغير طريق الميراث أو الوصية -أو على أي شخص اعتباري أن يمتلك نسبة %10من
رأس المال المصدر للشركة العاملة أو حقوق التصويت بها زيادة ملكيته فيها بنسبة %5ومضاعفاتها إال بعد الحصول على
موافقة مسبقة من الهيئة ،وذلك مع عدم اإلخالل بنسب الملكية القائمة وقت العمل بهذا القرار بشرط عدم زيادة هذه النسب
 إال بموافقة مسبقة من الهيئة.
 5
ال يجوز نقل ملكية أسهم الشركات العاملة في الفترة من تاريخ التأسيس وحتى الترخيص إال بموافقة مسبقة من الهيئة وأن
 يتوافر في المساهم الجديد ذات المتطلبات الواردة بالمادة الرابعة من هذا القرار.$b28$
  FROM laws WHERE law_no = 53 AND law_year = 2018
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $b28$على كل شخص طبيعي أو اعتباري يمتلك %5من رأس مال أو حقوق التصويت إلحدى الشركات العاملة أن يخطر الهيئة
 بذلك خالل أسبوعين من تاريخ تملكه لهذه النسبة.
ويحظر على أي شخص طبيعي – بغير طريق الميراث أو الوصية -أو على أي شخص اعتباري أن يمتلك نسبة %10من
رأس المال المصدر للشركة العاملة أو حقوق التصويت بها زيادة ملكيته فيها بنسبة %5ومضاعفاتها إال بعد الحصول على
