 إال بموافقة مسبقة من الهيئة.
 5
ال يجوز نقل ملكية أسهم الشركات العاملة في الفترة من تاريخ التأسيس وحتى الترخيص إال بموافقة مسبقة من الهيئة وأن
 يتوافر في المساهم الجديد ذات المتطلبات الواردة بالمادة الرابعة من هذا القرار.$b28$, '2018-04-26', 'active' FROM ins_art_53_2018__________________________________6;
WITH ins_art_53_2018__________________________________7 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 7, NULL, $b29$تقدم طلبات نقل ملكية أسهم الشركات العاملة إىل اهليئة ،ويرفق بالطلب ما يلي- :
 .1بيان يتضمن كمية ونسبة األوراق المالية أو حقوق التصويت محل التعامل.
 .2بيان بالمساهمات المباشرة وغير المباشرة في رأس مال أو حقوق التصويت بأي من الشركات العاملة األخرى في ذات
 النشاط متضمنا اسم الشركة ونسبة وكمية المساهمة وذلك بالنسبة لمقدم الطلب وأطرافه المرتبطة.
 .3أي اتفاق أو تنسيق ما بين أشخاص طبيعيين أو اعتباريين تتعلق بكيفية ممارسة حقوقهم في الجمعية العامة أو مجلس
 إدارة الشركة محل طلب التملك.
 .4اإلفصاح عن المستفيد النهائي لطالب التملك وفقا ً للقواعد واألحكام الواردة بالباب الثالث عشر من الالئحة التنفيذية
 لقانون سوق راس المال.
 .5إقرار من طالب التملك أو ممثله القانوني بصحة كافة المستندات والبيانات المقدمة للهيئة.
 .6بيان بالمؤهالت العلمية وبالخبرات العملية في مجال عمل الشركة بالنسبة لألشخاص الطبيعيين.
 .7بيان معتمد من طالب التملك باألحكام الصادرة ضده خالل الثالث سنوات السابقة على تقديم الطلب في إحدى الجرائم أو
المخالفات المنصوص عليها في األنشطة المالية غير المصرفية أو قانون الشركات أو قانون البنك المركزي والجهاز
المصرفي والنقد أو قانون مكافحة غسل األموال وتمويل اإلرهاب أو قانون حماية المنافسة ومنع الممارسات االحتكارية
 أو بجريمة ماسة بالشرف واألمانة ،أو تقديم إقرار بعدم صدور أية أحكام بشأن تلك الجرائم أو المخالفات.
 .8ما يفيد سداد مقابل خدمات فحص ودراسة طلب التملك.
وفى حالة طلبات التملك لنسبة %25أو أكثر من رأس المال أو حقوق التصويت ،يتم تقديم المستندات والبيانات اإلضافية
 التالية- :
 .1األهداف التي يرمى مقدم الطلب إلى تحقيقها من التملك.
 .2الخطة االستثمارية المستقبلية وتوجهاته فيما يتعلق بإدارة الشركة والسياسة التي ينوى إتباعها في تصريف
 شئونها.
 .3صحيفة الحالة الجنائية وشهادة بمدى صدور أحكام حجر أو إفالس لألشخاص الطبيعيين (أو ما يقابلها بالنسبة
 لألجانب).
 .4إذا كان الطالب بنكا أو مؤسسة مالية أجنبية يتعين تقديم ما يثبت خضوعه لرقابة سلطة رقابية في الدولة التي يقع
بها مقره الرئيسي تشابه اختصاصات البنك المركزي المصري أو اختصاصات الهيئة في مجال النشاط ،مع ارفاق
شهادة بالجزاءات أو التدابير الموقعة من الجهة الرقابية الخاضع لها الشخص االعتباري طالب التملك حال كونه
 بنك أجنبي أو مؤسسة مالية أجنبية.
 .5تعهد من الشخص االعتباري وممثله القانوني بإخطار الهيئة مسبقا ً في حال تغير السيطرة وااللتزام بإرسال هيكل
الملكية الجديد للشخص االعتباري متضمنا ُ كل من يملك %10أو أكثر من أسهمه أو حقوق التصويت به ،وضرورة
الحصول على موافقة الهيئة المسبقة في حال ترتب على تغيير السيطرة على الشخص االعتباري تجاوز النسب
 المحددة بهذا القرار.
 6
 6$b29$
  FROM laws WHERE law_no = 53 AND law_year = 2018
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
