الملكية الجديد للشخص االعتباري متضمنا ُ كل من يملك %10أو أكثر من أسهمه أو حقوق التصويت به ،وضرورة
الحصول على موافقة الهيئة المسبقة في حال ترتب على تغيير السيطرة على الشخص االعتباري تجاوز النسب
 المحددة بهذا القرار.
 6
 6$b29$, '2018-04-26', 'active' FROM ins_art_53_2018__________________________________7;
WITH ins_art_53_2018__________________________________8 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 8, NULL, $b30$يراعى عند البت يف طلبات احلصول على موافقة اهليئة على التملك االعتبارات التالية- :
 .1مدى توافر عناصر األهلية والكفاءة والخبرة العملية في مجال عمل الشركة في ضوء نسبة الملكية المطلوبة بالنسبة
 لألشخاص الطبيعيين.
 .2مدى مساهمة طالب التملك واألطراف المرتبطة به في الشركة المطلوب االستحواذ عليها وغيرها من الشركات العاملة
 في ذات النشاط وتأثير ذلك على السيطرة في ضوء نسبة الملكية المطلوبة.
 .3مدى صدور أحكام قضائية نهائية ضد مقدم الطلب بإشهار اإلفالس ،أو إدانته بجريمة ماسة بالشرف أو األمانة ،أو
بإحدى الجرائم المقيدة للحرية المنصوص عليها في للقوانين التي تشرف عليها الهيئة أو قانون البنك المركزي والجهاز
المصرفي والنقد أو في قانون مكافحة غسل األموال وتمويل اإلرهاب أو قانون حماية المنافسة ومنع الممارسات
 االحتكارية.
 .4مدى وجود تحقيقات تجريها الهيئة أو طلبات لتحريك الدعوى الجنائية بشأن مخالفات جسيمة للقوانين التي تشرف
عليها الهيئة سواء كانت ضد الشخص الطبيعي طالب التملك أو ضد رئيس مجلس اإلدارة أو العضو المنتدب للشركة
 طالبة التملك.
 .5االلتزام بإعمال نظام التصويت التراكمي في انتخاب أعضاء مجلس إدارة الشركة بما يسمح بالتمثيل النسبي في عضوية
 مجلس اإلدارة كلما أمكن ذلك.
وفي جميع األحوال؛ يجب الحصول على موافقة مجلس إدارة الهيئة في حالة طلبات التملك للشخص ومجموعته المرتبطة
 لشركة تمثل %10فأكثر من حجم السوق ألي نشاط ،وذلك في حالة نسب االستحواذ التالية- :
 ثلث رأس المال أو حقوق التصويت. 
 نصف رأس المال أو حقوق التصويت. 
 ثلثي رأس المال أو حقوق التصويت. 
 ثالثة أرباع رأس المال أو حقوق التصويت. 
 ويتم حساب حجم السوق لكل نشاط وفقا ً ألخر بيانات سنوية سابقة على تقديم طلب التملك.
 -6االلتزام بالبندين ( )10 ،9المنصوص عليهما في المادة الرابعة من هذا القرار في شأن طالب التملك (المساهم الرئيسي)
 والمستفيد النهائي.
وفي جميع األحوال ،يجب الحصول على موافقة مسبقة من الهيئة أو مجلس إدارة الهيئة بحسب األحوال قبل إجراء الفحص
النافي للجهالة ألي من الشركات العاملة في األنشطة المالية غير المصرفية وذلك وفقا ً للنموذج التي تضعه الهيئة في هذا
 الشأن7.$b30$
  FROM laws WHERE law_no = 53 AND law_year = 2018
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
