وفي جميع األحوال ،يجب الحصول على موافقة مسبقة من الهيئة أو مجلس إدارة الهيئة بحسب األحوال قبل إجراء الفحص
النافي للجهالة ألي من الشركات العاملة في األنشطة المالية غير المصرفية وذلك وفقا ً للنموذج التي تضعه الهيئة في هذا
 الشأن7.$b30$, '2018-04-26', 'active' FROM ins_art_53_2018__________________________________8;
WITH ins_art_53_2018__________________________________9 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 9, NULL, $b31$يُعتبر استمرار توافر المتطلبات الخاصة بهيكل ملكية الشركة الوارد بالمادة الرابعة من هذا القرار وكذا توافر الخبرات
والشروط في أعضاء مجلس اإلدارة أو القائمين على إدارة الشركة تبعا ً لكل نشاط ،أحد شروط استمرار الترخيص للشركة
 بمزاولة النشاط.
