 اليوم التالي لتاريخ نشره بالوقائع المصرية.
 - 8تم حذف عبارة (عدا البند رقم 2من المادة الثالثة منه) الواردة بالبند رقم 2من المادة الثانية عشرة بموجب قرار المجلس رقم 65بتاريخ .2020/4/8
 999ال تسري أحكام قرار مجلس إدارة الهيئة رقم 249بتاريخ 2023/11/29على الشركات السابق حصولها على ترخيص بمزاولة أي من
 األنشطة المالية غير المصرفية وتزاول النشاط فعلياً.
وعلى الشركات المرخص لها بمزاولة أحد األنشطة المالية غير المصرفية ولم تقم بمزاولة النشاط فعليا ً أن توفق أوضاعها باستيفاء المتطلبات
الالزمة لمزاولة النشاط وفقا ً ألحكام قرار مجلس إدارة الهيئة رقم ( )53لسنة 2018المشار إليه ،خالل مدة ال تجاوز ستة أشهر من تاريخ العمل
بهذا القرار ،وفى حال عدم التزام الشركات بتوفيق أوضاعها أو تقديم مبررات تقبلها الهيئة لمد مهلة مزاولة النشاط يعرض األمر على مجلس
 إدارة الهيئة للنظر في إلغاء الترخيص الممنوح لها.
 كما يلغى قرار مجلس إدارة الهيئة رقم 74لسنة .2019
 8
 10
