 ال يشترط توافر مؤسسة مالية أو مستثمر مؤهل. .1تقييم وتصنيف وترتيب األوراق المالية
 ال يشترط توافر مؤسسة مالية أو مستثمر مؤهل. .2االستشارات المالية عن األوراق المالية
 الشركات العاملة في مجال التأمين
يشترط أن تكون نسبة المساهمة المملوكة للشركات التامين وإعادة التامين
بها ال تقل عن %25من رأس المال ،على أن تكون شركة التأمين مصنفة
من قبل أحد جهات الت صنيف الدولية التالية وبما ال يقل عن الت صنيف قرين
 كل جهة:
