وفي حالة انخفاض هذه النسبببببببة بعد الترخيص بسبببببببب زيادات رؤوس
األموال ،بجوز استكمال هذه النسبة من المؤسسات المالية شريطة أال تقل
حقوق ملكيتها عن خمسبببببببة مليار جنيه وال يقل تصببببببنيفها االئتماني عن
 المستوى الدال على القدرة بالوفاء بااللتزامات (.)BBB+
 يشترط توافر مؤسسات مالية بنسبة ال تقل عن (.)%25 .2شركات الوساطة في التأمين /إعادة التأمين
 ال يشترط توافر مؤسسة مالية أو مستثمر مؤهل. .3شركات خبراء المعاينة وتقدير األضرار
 14تم تعديل البند رقم 1الخاص بتقييم وتصنيف وترتيب األوراق المالية من الجدول ( )1بموجب قرار مجلس إدارة الهيئة رقم 74بتاريخ 2019/6/20ثم تم
 التعديل بموجب قرار المجلس رقم 9بتاريخ ،2022/1/23ثم تم استبدال الجدول بموجب قرار مجلس إدارة الهيئة رقم 249بتاريخ ،2023/11/29على أن
 تلتزم شركات تقييم وتصنيف وترتيب األوراق المالية بإصدار وثيقة تأمين ضد األخطار المهنية وفقا ً للشروط التي تضعها الهيئة بما يتالءم مع حجم ونطاق
 المسئوليات ال مترتبة على مزاولة مهامها ،كما يجب استيفاء العضو المنتدب لهذه الشركات والعاملين بها من شاغلي الوظائف الرئيسية الخبرة الكافية في مجال
 تصنيف األوراق المالية أو في مجال تحليل االئتمان ودراسة الجدارة االئتمانية وفقا ً للمادة ( )285من الالئحة التنفيذية لقانون سوق رأس المال ،واجتياز العضو
 المنتدب لتلك الشركات المقابلة الشخصية بالهيئة واالختبارات الالزمة لشغل هذا المنصب.
 ويجب على الشركات المشار إليها مزاولة نشاطها وفقا ً لنموذج العمل المتبع لدى إحدى الجهات الدولية الواردة بقرار مجلس إدارة الهيئة رقم ( )71لسنة ،2009
 أو أن تقدم شهادة من إحدى هذه الجهات تفيد العمل وفقا ً للنموذج المتبع لديها.
 9
 ال يشترط توافر مؤسسة مالية أو مستثمر مؤهل. .4شركات خبراء التأمين االستشاريين
