طفق 0997

للدائرة الجنائية بمحكمة النقض عند نظر ا موضوع . إقامة الدعوى . طبقًا لما هو مقرر
بالمادة السابقة .

وإذا طعن فى الحكم الذى يصدر فى الدعوى الجديدة ‎٠‏ فلا يجوز أن يشترك فى نظرها
أحد القضاة الذين قرروا إقامعها .
مسادة (99/9) :

يُكلف الشهود بالحضور بناء على طلب الخصوم بواسطة أحد المحضرين أو رجال الضبط
قبل الجلسة بأربع وعشرين ساعة غير مواعيد المسافة ‎٠‏ ويُعلن لشخصه أو فى محل إقامته
بالطرق المقررة فى قانون المرافعات المدنية والتجارية . إلا فى حالة التليس بالجرهة.
فإنه يجوز تكليفهم بالحضور فى أى وقت ولو شفهيًا بواسطة أحد مأمورى الضبط القضائى
أو أحد رجال الضبط ‎٠‏ وبجوز أن يحضر الشاهد فى الجلسة بغير إعلان يناء على طلب الخصوم .


ول الاق
“وزيا 0
1 الجريدة الرسمية - العدد ‎١7‏ (تابع) فى 7؟ أبريل سنة ‎7١11‏
‏ومع عدم الإخلال بأحكام الفقرة الأولى من هذه المادة . يحدد الخصوم أسماء الشهود
وبياناتهم ووجه الاستدلال بهم . وتقرر المحكمة من ترى لزوم سماع شهادته , وإذا قررت المحكمة
عدم لزوم سماع شهادة أى منهم وجب عليها أن تسيب ذلك فى حكمها .
وللمحكمة أثناء نظر الدعوى أن تستدعى وتسمع أقوال أى شخص ولو بإصدار أمر بالضبط
والإحضار . إذا دعت الضرورة لذلك ‎١‏ ولها أن تأمر بتكليفه بالحضور فى جلسة أخرى .
وللمحكمة أن تسمع شهادة أى شخص يحضر من تلقاء نفسه لإبداء معلومات فى الدعوى .
مساية (45؟) :
على المحكمة أن تقرر تلاوة الشهادة التى أبديت فى التحقيق الابعدائى أو فى محضر
جمع الاستدلالات أو أمام الخبير . إذا تعذر سماع الشاهد لأى سبب من الأسباب .
مادة 89م" ) :
إذا صدر أمر بإحالة متهم بجناية إلى محكمة الجنايات ولم يحضر هو أو وكيله الخاص
يوم الجلسة بعد إعلانه قانونًا بأمر الإحالة وورقة التكليف بالحضور . يكون للمحكمة أن تحكم
فى غيبته ‎٠‏ ويجوز لها أن تؤجل الدعوى وتأمر بإعادة تكليفه بالحضور .
ومع عدم الإخلال بسلطة المحكمة المنصوص عليها بالمادة (740) من هنا القانون .
يكون الحكم حضوريا إذا مُكَل امتهم أو وكيله الخاص بالجلسة .
مادة (590) فقرتان اولى وثانية :
إذا حضر المحكوم عليه فى غيبته ‎٠‏ أو تُبض عليه . أو حضر وكيله الخاص
وطلب إعادة المحاكمة قيل سقوط العقوبة بمضى المدة . بحدد رئيس محكمة الاسدئئاف
أقرب جلسة لإعادة نظر الدعوى . ويُعرض المقبوض عليه محبوسًا بهذه الجلسة .
وللمحكمة أن تأمر بالإقراج عنه أو حبسه احتياطيًا حتى الانتهاء من نظر الدعوى .
ولا يجوز للمحكمة فى هذه الحالة التشديد عما قضى به الحكم الغيابى .
فإذا تخلف المحكوم عليه فى غيبته أو وكيله الخاص عن حضور الجلسة المحددة
لإعادة نظر دعواه , اعتبر الحكم ضده قائمًا ‎٠‏ فإذا حضر المحكوم عليه فى غيبته مرة أخرى
قبل سقوط العقوبة بمضى المدة تأمر النيابة بالقبض عليه . ويحدد رئيس محكمة الاسدثناف
أقرب جلسة لإعادة نظر الدعوى . ويُعرض محبوسًا بهذه الجلسة . وللمحكمة أن تأمر
بالإفراج عنه أو حيسه احتياطيًا حتى الانتهاء من نظر الدعوى .


