(المادة الثانية )

يستيدل بنصوص المواد (9 و44 و45) من قانون حالات وإجراءات الطعن
أمام محكمة النقض الصادر بالقانون رقم 01 لسنة 1984 ‎١‏ النصوص الآنية :
ماية (9) :

إذا قُدم الطعن أو أسبابه بعد الميعاد تقضى المحكمة يعدم قبوله شكلاً ,
وإذا كان الطعن مقبولاً وكان مينيًا على مخالفة القانون أو الخطأ فى تطبيقه أو تأويله .
تصحع المحكمة الخطأ وتحكم بمقتضى القانون .

وإذا كان الطعن مبنيًا على بطلان فى الحكم أو بطلان فى الإجراءات أثّر فيه .
تنقض المحكمة الحكم , وتنظر موضوعه . ويتيع فى ذلك الأصول المقررة فانوثًا عن الجرية
التى وقعت ‎٠‏ ويكون الحكم الصادر فى جميع الأحوال حضوريًا .
مادة 449) :

إذا كان الحكم المطعون فيه صادر) بقبول دفع قانونى مائع من السير فى الدعوى .
أو صادر) قبل الفصل فى الموضوع وانينى عليه منع السير فى الدعوى ونقضته محكمة النقض .
أعيدت القضية إلى المحكمة التى أصدرته للحكم فيها من جديد مُشككّلة من قضاة آخرين .

ولا يجوز لمحكمة الإعادة أن تحكم بعكس ما قضت به محكمة النقض .

كما لا يجوز لها فى جميع الأحوال . أن تحكم بعكس ما قررته الهيئة العامة
للمواد الجنائية بمحكمة النقض ,
مادة (45) :

مع عدم الإخلال بالأحكام المتقدمة, إذا كان الحكم صادر) حضوريًا بعقوبة الإعدام
يجب على النيابة العامة أن تعرض القضية على محكمة النقض مشفوعة بمذكرة برأيها
فى الحكم . وذلك فى الميعاد المبين بالمادة (4) وتحكم المحكمة طبقًا لما هو مقرر فى الفقرة الثانية
من المادة (7"8) والفقرة الغانية من ال مادة (9").


