أو المستندات أو التحريات أو المعلومات المزيدة لهذا الطلب .
مادة (4) فقرة أؤلى :
يكون الإدراج على أى من القائمتين لمدة لا تجاوز خمس سنئوات .
( ا مادة الرابعة )
