الكيانات الإرهابية والإرهابيين بند جديد برقم (0): نصه الآأتى :
مادة (؟) فقرة ثانا بند (8):
ه - حظر ممارسة كافة الأنشطة الأعلية أو الدعوية تحت أى مسمى .
( المادة الخامسة )
يضاف إلى القانون رقم 4 لسئة ‎٠١١6‏ فى شأن تنظيم قوائم الكيانات الإرهابية
والإرهابيين مادة جديدة برقم (8 مكرر))؛ نصها الآتى :
مادة (م مكرر)):
للنائب العام إذا توافرت معلومات أو دلائل جدية على وجود أموال ثابعة أو منقولة
متحصلة من أنشطة أى إرهابى أو كيان إرهابى مدرج أو غير مدرج على قوائم الكيانات
الإرهابية والإرهابيين, أو تستخدم فى تمويله بأى صورة كانت أو فى تمويل المنعسبين إليه
أو المرتبطين به » أن يأمر بالتحفظ على هذه الأموال ومنع مالكيها أو حائزيها من التصرف فيها .
ويعرض أمر التحفظ وال منع من التصرف على الدائرة المنتصوص عليها فى المادة (9)
من هنا القانون خلال شهر من تاريخ صدوره. للنظر فى تأبيده أو إلغائه أو تعديله .


