مادة (80 مكرر)) :

بجراعاة أحكام الرد المنصوص عليها فى قانون المرافعات ال مدنية والتجاربية .
يودع طالب الرد عند العقرير به ثلاثة آلاف جنيه على سبيل الكفالة. ويجب على قلم
الكتّاب تحديد جلسة فى موعد لا يجاوز أربعًا وعشرين ساعة من تاربخ تقديم الطلب
ويوقع طالب الرد بما يفيد علمه بالجلسة .

وعلى القاضى المطلورب رده أن يجيب بالكتكابة على وقائع الرد وأسيابه
خلال الأربع والعشرين ساعة التالية لاطلاعه .

وتقوم الدائرة العى تنظر طلب الرد بتحقيق الطلب فى غرفة المشورة . ثم تحكم فيه
فى موعد لا يجاوز أسبوعًا من تاريخ التقرير .


