(ج) الجريمة الإرهابية : كل جريمة منصوص عليها فى هذا القانون . وكذا كل جناية
أو جنحة ترتكب باستخدام إحدى وسائل الإرهاب أو بقصد تحقيق أو تنفيذ
غرض إرهابى , أو بقصد الدعوة إلى ارتكاب أية جريمة نما تقدم أو التهديد بها ,
وذلك دون إخلال بأحكام قانون العقوبات .

(د) الأسلحة التقليدية : الأسلحة والذخائر والمفرقعات والمواد الجيلاتينية المنصوص
عليها قانونًا .

(ه ) الأسلحة غير التقليدية : الأسلحة والمواد النووية والكيماوية والبيولوجية
