أو سائلة » أو غازية أو بخارية . أي كان مصدرها أو طريقة إنتاجها , لها القدرة
والصلاحية على إزهاق الأرواح أو إحداث إصابات بدنية أو نفسية خطيرة بها ,
أو إلحاق الضرر بالبيئة أو بالمبانى والمنشآت .

(و) الأموال : جميع الأصول أو الممتلكات أيا كان نوعها . سواء كانت مادية
أو معنوية . منقولة أو ثابتة , بما فى ذلك المستندات والعملات الوطنية
أو الأجنبية , والأوراق المالية أو التجارية . والصكوك والمحررات المثبتة لكل
ما تقدم وأيّا كان شكلها بما فى ذلك الشكل الرقمى أو الإلكترونى » وجميع
الحقوق المتعلقة بأى منها .

