وتكون العقوبة الإعدام إذا ترتب على الإكراه أو الحمل أو المنع وفاته .

)١7( ‏مسادة‎

يعاقب بالسجن المؤبد كل من ارتكب جرية من جرائم مويل الإرهاب إذا كان التمويل
لإرهابى , وتكون العقوبة الإعدام إذا كان التمويل لجماعة إرهابية أو لعمل إرهابى .

وفى الأحوال التى ترتكب فيها الجريمة بواسطة جماعة إرهابية , يعاقب المسئول
عن الإدارة الفعلية لهذه الجماعة بالعقوبة المقررة فى الفقرة السابقة من هذه المادة ما دامت
الجريمة قد ارتكبت لحساب الجماعة أو لمصلحتها .

كما تعاقب الجماعة الإرهابية بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز ثلاثة
ملايين جنيه » وتكون مسئولة بالتضامن عن الوفاءبما يحكم به من عقوبات مالية
أو تعويضات .

)١1( ‏مادة‎

يُعاقب بالسجن المؤبد كل من سعى أو تخابر لدى دولة أجنبية , أو أية جمعية
أو هيئة أو منظمة أو جماعة أو عصابة أو غيرها يكون مقرها داخل مصر أو خارجها ,
أو لدى أحد ممن يعملون لمصلحة هذه الدولة الأجنبية أو أى من الجهات المذكورة ,
وذلك بهدف ارتكاب أو الإعداد لارتكاب جريمة إرهابية داخل مصر ء أو ضد أى من
مواطنيها أو مصالحها أو ممتلكاتها أو مقار ومكاتب بعثاتها الدبلوماسية أو القنصلية
أو مؤسساتها أو فروع مؤسساتها فى الخارج ؛ أو ضد أى من العاملين فى أى من الجهات
السابقة . أو ضد أى من المتمتعين بحماية دولية .

وتكون العقوبة الإعدام إذا وقعت الجريمة الإرهابية موضوع السعى أو التخابر ,
أو شرع فى ارتكابها .


