قلب نظام الحكم أو تغيير دستور الدولة أو نظامها الجمهورى أو شكل الحكومة .
مادة (19)
يعاقب بالسجن المشدد مدة لا تقل عن عشر سنين , كل من ارتكب عملاً إرهابيا من
