الإرهابى وفاة شخص تكون العقوبة الإعدام .
وفى الأحوال التى ترتكب فيها الجريمة بواسطة جماعة إرهابية » يعاقب المسئول عن
الإدارة الفعلية لهذه الجماعة بالعقوبة المقررة فى الفقرة الأولى من هذه المادة . ما دامت
الجريمة قد ارتكبت لحساب هذه الجماعة أو لمصلحتها .


