وتكون العقوبة السجن المؤبد إذا كان محل الجريمة سلاحًا من الأسلحة غير التقليدية ,
فإذا نتج عن استخدام السلاح التقليدى أو غير التقليدى أو المواد المذكورة وفاة شخص
فتكون العقوبة الإعدام .
