- حظر الاقتراب أو التردد على أماكن أو محال معينة .

- الإلزام بالوجود فى أماكن معينة فى أوقات معينة

. ‏حظر العمل فى أماكن معينة أو مجال أنشطة محددة‎ - ١

- حظر استخدام وسائل اتصال معينة أو المنع من حيازتها أو إحرازها .

- الإلزام بالاشتراك فى دورات إعادة تأهيل .

وفيما عدا التدبير الأول لا يجوز أن تزيد مدة التدبير على خمس سنوات .

ويعاقب كل من يخالف التدبير المحكوم به بالحبس مدة لا تقل عن ستة أشهر .

وفى جميع الحالات؛ يترتب على الحكم بالإدانة فى جريمة إرهابية فقد شرط حسن
السمعة والسيرة اللازمين لتولى الوظائف العامة أو الترشح للمجالس النيابية .

مسادة (/؟)

يعفى من العقوبات المقررة للجرائم المشار إليها فى هذا القانون كل من بادر من الجناة
بإبلاغ السلطات المختصة قبل البدء فى تنفيذ الجريمة » ويجوز للمحكمة الإعفاء من
العقوبة إذا حصل البلاغ بعد تنفيذ الجريمة وقبل البدء فى التحقيق , وذلك إذا مكن
الجانى السلطات من القبض على مرتكبى الجريمة الآخرين ؛ أو على مرتكبى جريمة أخرى
مماثلة لها فى النوع والخطورة .


الجريدة الرسمية - العدد ‎٠‏ (مكرر) فى ‎١0‏ أغسطس سنة ‎"١ 7.0١6‏
مسادة (59؟)

مع عدم الإخلال بحقوق الغير حسنى النية , تقضى المحكمة فى كل حكم يصدر
بالإدانة فى جريمة إرهابية » فضلاً عن العقوبة المقررة للجريمة . بمصادرة الأموال والأمتعة
والأسلحة والأدوات والمستندات . وغيرها ما استخدم فى ارتكاب الجريمة أو تحصل عنها ,
وبحل الجماعة الإرهابية وإغلاق مقارها وأمكنتها فى الداخل والخارج . فضلاً عن إغلاق
أى مكان تم فيه تصنيع أو تصميم الأسلحة بمختلف أنواعها , المستخدمة فى ارتكاب أية
جريمة إرهابية . وغيرها ما يكون قد استعمل أو أعد للاستعمال من قبل الإرهابى
أو الجماعة الإرهابية .

كما تقضى المحكمة , عند الحكم بالإدانة بمصادرة كل مال متى ثبت أنه مخصص
للصرف منه على الأعمال الإرهابية .

