الأحكام الإجرائية
مسادة (+1)

لأمور الضبط القضائى ؛ لدى قيام خطر من أخطار جريمة الإرهاب ولضرورة تقتتضيها
مواجهة هذا الخطر . الحق فى جمع الاستدلالات عنها والبحث عن مرتكبيها والتحفظ
عليهم لدة لا تجاوز أربع وعشرين ساعة .

ويحرر مأمور الضبط القضائى محضراً بالإجراءات . ويعرض المتحفظ عليه صحبة
المحضر على النيابة العامة أو سلطة التحقيق المختصة بحسب الأحوال .

وللنيابة العامة أو سلطة التحقيق المختصة ., لذات الضرورة المنصوص عليها فى
الفقرة الأولى من هذه المادة وقبل انقضاء المدة المنصوص عليها فيها , أن تأمر باستمرار
التحفظ , لمرة واحدة , مدة لا تجاوز سبعة أيام » ويصدر الأمر مسبيًا من محام عام على
الأقل أو ما يعادلها .


