وتحسب مدة التحفظ ضمن مدة الحبس الاحتياطى . ويجب إبداع المتهم فى أحد
الأماكن المخصصة قانونًا .
وتتبع فى التظلم من أمر استمرار التتحفظ الأحكام المقررة بالفقرة الأولى من المادة (44)
من هذا القانون .
مسادة ‎)1١(‏
‏يبلغ مأمور الضبط القضائى كل من يتحفظ عليه وفقًا للمادة (20) من هذا القانون
بأسباب ذلك ‎٠‏ ويكون له حق الاتصال بمن يرى إبلاغه من ذويه بما وقع والاستعانة بمحام ,
وذلك دون الإخلال بمصلحة الاستدلال .
مادة (13)
على مأمور الضبط القضائى خلال مدة التتحفظ المنصوص عليها فى المادة (4-0)
من هذا القانون . وقبل انقضائها , تحرير محضر بالإجراءات وسماع أقوال المتحفظ عليه
وعرضه صحبة المحضر على النيابة العامة أو سلطة التحقيق المختصة لاستجوابه خلال ثمان
وأربعين ساعة من عرضه عليها , والأمر بحبسه احتياطيًا أو بالإفراج عنه .
مادة ("15)
تكون للنيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال . أثناء التحقيق
فى جريمة إرهابية , بالإضافة إلى الاختصاصات المقررة لها قانونًا . السلطات المقررة
لقاضى التحقيق , وتلك المقررة لمحكمة الجنح المستأنفة منعقدة فى غرفة المشورة . وذلك
وفمًا لذات الاختصاصات والقيود والمدد المنصوص عليها بالمادة ‎)١51(‏ من قانون
الإجراءات الجنائية .
مسادة (11)
للمتهم ولغيره من ذوى الشأن أن يستأنف بدون رسوم الأمر الصادر بحبسه احتياطيً
