وذلك بعد سماع أقوال النيابة العامة أو سلطة التحقيق المختصة ودفاع المستأنف ,
فإذا انقضت هذه المدة دون الفصل تعين الإفراج عن المتهم المقبوض عليه فوراً .
مسادة (10)
فى الأحوال التى يجوز فيها التحفظ على مرتكب جريمة إرهابية أو حبسه احتياطيًا ,
