مسبيًا من النيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال . بتفتيش مسكن
الملتتحفظ عليه أو المحبوس احتياطيًا . وضبط الأشياء والمتعلقات الخاصة بالجريمة
التى يجرى التفتيش بشأنها .
مسادة (15)
للنيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال . فى جريمة إرهابية أن
تأذن بأمر مسبب لمدة لا تزيد على ثلاثين يوم , بمراقبة وتسجيل المحادثات والرسائل التى
ترد على وسائل الاتصال السلكية واللاسلكية وغيرها من وسائل الاتصال الحديثة2,
وتسجيل وتصوير ما يجرى فى الأماكن الخاصة أو عبر شبكات الاتصال أو المعلومات أو
المواقع الإلكترونية وما يدون فيها . وضبط المكاتبات والرسائل العادية أو الإلكترونية
والمطبوعات والطرود والبرقيات بجميع أنواعها .
ويجوز تجديد الأمر المشار إليه فى الفقرة الأولى من هذه المادة مدة أو مددا أخرى مماثلة .
