مسادة (14)
للنائب العام أو من يفوضه من المحامين العامين على الأقل أو سلطة التحقيق
المختصة . بحسب الأحوال , أن يأمر بالاطلاع أو الحصول على أية بيانات أو معلومات
تتعلق بالحسابات أو الودائع أو الأمانات أو الخزائن أو المعاملات المتعلقة بها . إذا اقتضى
ذلك كشف الحقيقة فى أعمال الاستدلال أو التحقيق على ارتكاب المتهم أو اشتراكه
فى أية جريمة إرهابية قامت الدلائل الكافية على وقوعها .
مادة (19)
للنيابة العامة أو سلطة التحقيق المختصة ‎٠‏ بحسب الأحوال ؛ فى الجرائم المنتصوص
عليها بالمواد (؟١. ‎1١9 1١6‏ ؟١5)‏ من هذا القانون . أن تصدر أمراً مؤقمًا بغلق المقار .
والأماكن . والمساكن , ومحال الإيواء على أن يصدر القرار من رئيس نيابة على الأقل ,
وتعتبر الأمتعة والأثاث المضبوط فيها فى حكم الأشياء المحجوز عليها إداريًا بمجرد
ضبطها حتى يفصل فى الدعوى نهائيًا . وتسلم بعد جردها وإثباتها فى محضر إلى حارس
يكلف بحراسة الأختام الموضوعة على المقر أو المكان أو المحل أو المسكن المغلق . فإن لم
توجد مضبوطات كلف بالحراسة على الأختام وبالطريقة ذاتها . ويترتب على صدور الحكم
بالبراءة سقوط أمر الغلق .
وللنيابة العامة أو سلطة التحقيق المختصة وقف المواقع المنصوص عليها فى الفقرة
الأولى من المادة (89؟) من هذا القانون , أو حجبها . أو حجب ما يتضمنه أى وجه من
أوجه الاستخدام المنصوص عليها فى هذه المادة . والتتحفظ على الأجهزة والمعدات
المستخدمة فى الجريمة .
