وتخصص دوائر فى المحاكم الابتدائية برئاسة رئيس بالمحكمة على الأقل لنظر الجنح
من الجرائم الإرهابية والجرائم المرتبطة بهذه الجنح .
كما تخصص دوائر فى المحاكم الابتدائية برئاسة رئيس بالمحكمة على الأقل وعضوين
أحدهما على الأقل بدرجة رئيس لنظر الطعون بالاستئناف فى الأحكام الصادرة فى هذه
الجرائم .
ويفصل فى القضايا المشار إليها فى هذه المادة على وجه السرعة . وطبقًا للإجراءات
المقررة فى هذا القانون وقانون الإجراءات الجنائية .
مسادة ‎)0١(‏
‏تختص النيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال ؛ أو المحكمة
التى تنظر أو تحال إليها أية جريمة إرهابية » بنظر الجرائم المرتبطة بها .
مادة (09)
لا تنتقضى الدعوى الجنائية فى الجرائم الإرهابية . ولا تسقط العقوبة المحكوم بها
فيها بمضى المدة .
مادة (07)
لرئيس الجمهورية . متى قام خطر من أخطار الجرائم الإرهابية أو ترتب عليها كوارث
بيئية » أن يصدر قراراً باتخاذ التدابير المناسبة للمحافظة على الأمن والنظام العام , بما فى
ذلك إخلاء بعض المناطق أو عزلها أو حظر التجول فيها . على أن يتضمن القرار تحديد
المنطقة المطبق عليها لمدة لا تجاوز ستة أشهر .
ويجب عرض هذا القرار على مجلس النواب خلال الآيام السبعة التالية ليقرر ما يراه
بشأنه . فإذا كان المجلس فى غير دور الانعقاد العادى وجبت دعوته للانعقاد فوراً ,
فإذا كان المجلس غير قائم وجب أخذ موافقة مجلس الوزراء » على أن يعرض على مجلس
النواب الجديد فى أول اجتماع له . ويصدر القرار بموافقة أغلبية عدد أعضاء المجلس ,
فإذا لم يعرض القرار فى الميعاد المشار إليه . أو عرض ولم يقره المجلس اعتبر القرار كأن
لم يكن ما لم ير المجلس خلاف ذلك .


