مادة (01)

تلتزم الدولة بإبرام وثيقة تأمين إجبارى شامل مع شركات التأمين . لتغطية جميع
الأخطار الناجمة عن الجرائم الإرهابية التى تصيب أى فرد من أفراد القوات المسلحة أو
قوات الشرطة المكلفة بمكافحة الإرهاب , حال تصديها لتلك الجرائم , بما فى ذلك حالات
الوفاة أو العجز الكامل أو الجزئى . على أن تتضمن الوثيقة التزام الشركة بسداد
تعويضات مؤقتة للمضرورين فور وقوع الخطر خصمً من مبلغ التأمين .

وفى جميع الأحوال . تلتزم شركة التأمين بسداد مبلغ التأمين وفقًا للوثيقة . وذلك
دون الإخلال بحق المضرور أو ورثته أو شركة التأمين فى اللجوء للقضاء .

ويتم التأمين لدى شركة أو أكثر من شركات التأمين المسجلة لدى الهيئة العامة
للرقابة المالية . والمرخص لها بمزاولة تلك الأنشطة التأمينية طبقًا لأحكام قانون الإشراف
والرقابة على التأمين فى مصر .

