يعاقب بالسجن المؤبد كل من ارتكب جرية من جرائم مويل الإرهاب إذا كان التمويل
لإرهابى , وتكون العقوبة الإعدام إذا كان التمويل لجماعة إرهابية أو لعمل إرهابى .

وفى الأحوال التى ترتكب فيها الجريمة بواسطة جماعة إرهابية , يعاقب المسئول
عن الإدارة الفعلية لهذه الجماعة بالعقوبة المقررة فى الفقرة السابقة من هذه المادة ما دامت
