كما تعاقب الجماعة الإرهابية بغرامة لا تقل عن مائة ألف جنيه ولا تجاوز ثلاثة
ملايين جنيه » وتكون مسئولة بالتضامن عن الوفاءبما يحكم به من عقوبات مالية
أو تعويضات .

