يُعاقب بالسجن المؤبد كل من سعى أو تخابر لدى دولة أجنبية , أو أية جمعية
أو هيئة أو منظمة أو جماعة أو عصابة أو غيرها يكون مقرها داخل مصر أو خارجها ,
