أو مؤسساتها أو فروع مؤسساتها فى الخارج ؛ أو ضد أى من العاملين فى أى من الجهات
السابقة . أو ضد أى من المتمتعين بحماية دولية .

وتكون العقوبة الإعدام إذا وقعت الجريمة الإرهابية موضوع السعى أو التخابر ,
أو شرع فى ارتكابها .


