قام بأية طريقة مباشرة أو غير مباشرة . وبقصد ارتكاب جرية إرهابية فى الداخل أو الخارج ,
بإعداد أو تدريب أفراد على صنع أو استعمال الأسلحة التقليدية أو غير التقليدية . أو وسائل
الاتصال السلكية أو اللاسلكية أو الإلكترونية , أو أية وسيلة تقنية أخرى ‎٠‏ أو قام بتعليم
فنون حربية أو أساليب قتالية أو تقنية » أو مهارات , أو حيل ‎٠‏ أو غيرها من الوسائل ,
أي كان شكلها لاستخدامها فى ارتكاب جريهة إرهابية ‏ أو حرض على شىء مما ذكر .

ويعاقب بالسجن مدة لا تقل عن سبع سنين كل من تلقى التدريب أو التعليم
المنصوص عليه فى الفقرة السابقة من هذه المادة » أو وجد فى أماكنها بقصد الإعداد
أو ارتكاب جرية من الجرائم المشار إليها بالفقرة الأولى من هذه المادة .

)١5( ‏مسادة‎

يُعاقب بالسجن المؤبد أو السجن المشدد الذى لا تقل مدته عن عشر سنين ,
كل من استولى أو هاجم أو دخل بالقوة أو العنف أو التهديد أو الترويع . أحد المقار الرئاسية
أو مقار المجالس النيابية أو مجلس الوزراء أو الوزارات أو المحافظات أو القوات المسلحة
أو المحاكم أو النيابات أو مديريات الأمن أو أقسام ومراكز الشرطة أو السجون أو الهيئات
أو الأجهزة الأمنية أو الرقابية أو الأماكن الأثرية أو المرافق العامة أو دور العبادة أو التعليم
أو المستشفيات أو أى من المبانى أو المنشآت العامة بقصد ارتكاب جريمة إرهابية .

وتسرى أحكام الفقرة الأولى من هذه المادة على كل من وضع أجهزة أو مواد فى أى
من المقار السابقة . متى كان من شأن ذلك تدميرها أو إلحاق الضرر بها . أو بأى من
الأشخاص الموجودين بها أو المترددين عليها , أو هدد بارتكاب أى من هذه الأفعال .

وتكون العقوبة السجن المؤبد إذا وقع الفعل باستعمال السلاح . أو من أكثر من
شخص ., أو قام الجانى بتدمير أو إتلاف المقر , أو قاوم بالقوة السلطات العامة أثناء تأدية
وظيفتها لاستعادة المقر . فإذا ترتب على ارتكاب أى من الأفعال السابقة وفاة شخص
تكون العقوبة الإعدام .


