عليها فى الفقرة الأولى من هذه المادة ‏ أو وسائل الانتقال لشخص يتمتع بحماية دولية ,
إذا كان من شأن هذا الهجوم أن يعرض سلامته أو حريته للخطر , أو لمجرد التهديد
بارتكاب هذا الفعل .
وتكون العقوبة السجن المؤيد إذا وقع الفعل باستعمال السلاح أو من أكثر من شخص ,
فإذا ترتب على الفعل وفاة شخص تكون العقوبة الإعدام .
