أو لمنع هذه السلطات من أداء وظيفتها .

وتكون العقوبة الإعدام إذا نشأ عن الفعل وفاة شخص .

مسادة (0؟)

يعاقب بالسجن المشدد مدة لا تقل عن سبع سنين كل من أتلف عمداً أو خرب أو دمر
