ولو بصفة مؤقتة , تكون العقوبة السجن المؤيد .

فإذا ترتب على ارتكاب الجرائم المشار إليها بالفقرتين السابقتين من هذه المادة وفاة
شخص تكون العقوبة الإعدام .

وفى جميع الأحوال , تقضى المحكمة بمصادرة الآلات والآدوات المستخدمة فى الجريمة ,
وبإعادة الحال إلى ما كانت عليه قبل الجريمة على نفقة المحكوم عليه , وبإلزامه بأداء
قيمة التلفيات .


