الإرهابية إلا بإذن من رئيس المحكمة المختصة؛ ويعاقب بغرامة لا تقل عن عشرين ألف جنيه
ولا تجاوز مائة ألف جنيه كل من خالف هذا الحظر .


الجريدة الرسمية - العدد " (مكرر) فى ‎١0‏ أغسطس سنة 0١١؟‏
مسادة (/17؟)

للمحكمة فى أية جريمة إرهابية . فضلاً عن الحكم بالعقوبة المقررة أن تقضى ,
بتدبير أو أكثر , من التدابير الآتية :

. ‏إبعاد الأجنبى عن البلاد‎ - ١

. ‏حظر الإقامة فى مكان معين أو فى منطقة محددة‎ - ١

- الإلزام بالإقامة فى مكان معين .

- حظر الاقتراب أو التردد على أماكن أو محال معينة .

- الإلزام بالوجود فى أماكن معينة فى أوقات معينة

. ‏حظر العمل فى أماكن معينة أو مجال أنشطة محددة‎ - ١

- حظر استخدام وسائل اتصال معينة أو المنع من حيازتها أو إحرازها .

- الإلزام بالاشتراك فى دورات إعادة تأهيل .

وفيما عدا التدبير الأول لا يجوز أن تزيد مدة التدبير على خمس سنوات .

ويعاقب كل من يخالف التدبير المحكوم به بالحبس مدة لا تقل عن ستة أشهر .

وفى جميع الحالات؛ يترتب على الحكم بالإدانة فى جريمة إرهابية فقد شرط حسن
السمعة والسيرة اللازمين لتولى الوظائف العامة أو الترشح للمجالس النيابية .

مسادة (/؟)

يعفى من العقوبات المقررة للجرائم المشار إليها فى هذا القانون كل من بادر من الجناة
بإبلاغ السلطات المختصة قبل البدء فى تنفيذ الجريمة » ويجوز للمحكمة الإعفاء من
العقوبة إذا حصل البلاغ بعد تنفيذ الجريمة وقبل البدء فى التحقيق , وذلك إذا مكن
الجانى السلطات من القبض على مرتكبى الجريمة الآخرين ؛ أو على مرتكبى جريمة أخرى
مماثلة لها فى النوع والخطورة .


الجريدة الرسمية - العدد ‎٠‏ (مكرر) فى ‎١0‏ أغسطس سنة ‎"١ 7.0١6‏
مسادة (59؟)

مع عدم الإخلال بحقوق الغير حسنى النية , تقضى المحكمة فى كل حكم يصدر
بالإدانة فى جريمة إرهابية » فضلاً عن العقوبة المقررة للجريمة . بمصادرة الأموال والأمتعة
والأسلحة والأدوات والمستندات . وغيرها ما استخدم فى ارتكاب الجريمة أو تحصل عنها ,
وبحل الجماعة الإرهابية وإغلاق مقارها وأمكنتها فى الداخل والخارج . فضلاً عن إغلاق
أى مكان تم فيه تصنيع أو تصميم الأسلحة بمختلف أنواعها , المستخدمة فى ارتكاب أية
جريمة إرهابية . وغيرها ما يكون قد استعمل أو أعد للاستعمال من قبل الإرهابى
أو الجماعة الإرهابية .

كما تقضى المحكمة , عند الحكم بالإدانة بمصادرة كل مال متى ثبت أنه مخصص
للصرف منه على الأعمال الإرهابية .

لباب الشانى
الأحكام الإجرائية
مسادة (+1)

لأمور الضبط القضائى ؛ لدى قيام خطر من أخطار جريمة الإرهاب ولضرورة تقتتضيها
مواجهة هذا الخطر . الحق فى جمع الاستدلالات عنها والبحث عن مرتكبيها والتحفظ
عليهم لدة لا تجاوز أربع وعشرين ساعة .

ويحرر مأمور الضبط القضائى محضراً بالإجراءات . ويعرض المتحفظ عليه صحبة
المحضر على النيابة العامة أو سلطة التحقيق المختصة بحسب الأحوال .

وللنيابة العامة أو سلطة التحقيق المختصة ., لذات الضرورة المنصوص عليها فى
الفقرة الأولى من هذه المادة وقبل انقضاء المدة المنصوص عليها فيها , أن تأمر باستمرار
التحفظ , لمرة واحدة , مدة لا تجاوز سبعة أيام » ويصدر الأمر مسبيًا من محام عام على
الأقل أو ما يعادلها .


1 الجريدة الرسمية - العدد *" (مكرر) فى ‎١0‏ أغسطس سنة 0١١؟‏
وتحسب مدة التحفظ ضمن مدة الحبس الاحتياطى . ويجب إبداع المتهم فى أحد
الأماكن المخصصة قانونًا .
وتتبع فى التظلم من أمر استمرار التتحفظ الأحكام المقررة بالفقرة الأولى من المادة (44)
من هذا القانون .
مسادة ‎)1١(‏
‏يبلغ مأمور الضبط القضائى كل من يتحفظ عليه وفقًا للمادة (20) من هذا القانون
بأسباب ذلك ‎٠‏ ويكون له حق الاتصال بمن يرى إبلاغه من ذويه بما وقع والاستعانة بمحام ,
وذلك دون الإخلال بمصلحة الاستدلال .
مادة (13)
على مأمور الضبط القضائى خلال مدة التتحفظ المنصوص عليها فى المادة (4-0)
من هذا القانون . وقبل انقضائها , تحرير محضر بالإجراءات وسماع أقوال المتحفظ عليه
وعرضه صحبة المحضر على النيابة العامة أو سلطة التحقيق المختصة لاستجوابه خلال ثمان
وأربعين ساعة من عرضه عليها , والأمر بحبسه احتياطيًا أو بالإفراج عنه .
مادة ("15)
تكون للنيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال . أثناء التحقيق
فى جريمة إرهابية , بالإضافة إلى الاختصاصات المقررة لها قانونًا . السلطات المقررة
لقاضى التحقيق , وتلك المقررة لمحكمة الجنح المستأنفة منعقدة فى غرفة المشورة . وذلك
وفمًا لذات الاختصاصات والقيود والمدد المنصوص عليها بالمادة ‎)١51(‏ من قانون
الإجراءات الجنائية .
مسادة (11)
للمتهم ولغيره من ذوى الشأن أن يستأنف بدون رسوم الأمر الصادر بحبسه احتياطيً
أو بمد هذا الحبس أمام المحكمة المختصة .


الجريدة الرسمية - العدد ‎٠#‏ (مكرر) فى ‎١0‏ أغسطس سنة ‎2.0١0‏ "ا"
وتفصل المحكمة فى الاستئناف بقرار مسبب خلال ثلاثة أيام من تاريخ تقديمه ,
وذلك بعد سماع أقوال النيابة العامة أو سلطة التحقيق المختصة ودفاع المستأنف ,
فإذا انقضت هذه المدة دون الفصل تعين الإفراج عن المتهم المقبوض عليه فوراً .
مسادة (10)
فى الأحوال التى يجوز فيها التحفظ على مرتكب جريمة إرهابية أو حبسه احتياطيًا ,
ولدى قيام خطر أو خوف من ضياع الأدلة » لمأمور الضبط القضائى أن يستصدر إذنً
مسبيًا من النيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال . بتفتيش مسكن
الملتتحفظ عليه أو المحبوس احتياطيًا . وضبط الأشياء والمتعلقات الخاصة بالجريمة
التى يجرى التفتيش بشأنها .
مسادة (15)
للنيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال . فى جريمة إرهابية أن
تأذن بأمر مسبب لمدة لا تزيد على ثلاثين يوم , بمراقبة وتسجيل المحادثات والرسائل التى
ترد على وسائل الاتصال السلكية واللاسلكية وغيرها من وسائل الاتصال الحديثة2,
وتسجيل وتصوير ما يجرى فى الأماكن الخاصة أو عبر شبكات الاتصال أو المعلومات أو
المواقع الإلكترونية وما يدون فيها . وضبط المكاتبات والرسائل العادية أو الإلكترونية
والمطبوعات والطرود والبرقيات بجميع أنواعها .
ويجوز تجديد الأمر المشار إليه فى الفقرة الأولى من هذه المادة مدة أو مددا أخرى مماثلة .
مسادة (17)
تسرى أحكام المواد 04" مكرراً (أ) و8١٠١‏ مكرراً (ب) و8١٠7‏ مكرراً (ج)
و١7‏ مكرراً (د) من قانون الإجراءات الجنائية فى الأحوال التى يظهر فيها من الاستدلال
أو التحقيق دلائل كافية على الاتهام بارتكاب أى جريمة إرهابية .
وللسلطات المختصة اتخاذ التدابير التحفظية اللازمة . بما فى ذلك تجميد الأموال ,
والمنع من التصرف فيها أو إدارتها . أو المنع من السفر . على أن تلتزم بالأحكام والإجراءات
المنصوص عليها فى المواد المذكورة بالفقرة الأولى من هذه المادة .


5 الجريدة الرسمية - العدد *" (مكرر) فى ‎١0‏ أغسطس سنة 0١١؟‏
مسادة (14)
للنائب العام أو من يفوضه من المحامين العامين على الأقل أو سلطة التحقيق
المختصة . بحسب الأحوال , أن يأمر بالاطلاع أو الحصول على أية بيانات أو معلومات
تتعلق بالحسابات أو الودائع أو الأمانات أو الخزائن أو المعاملات المتعلقة بها . إذا اقتضى
ذلك كشف الحقيقة فى أعمال الاستدلال أو التحقيق على ارتكاب المتهم أو اشتراكه
فى أية جريمة إرهابية قامت الدلائل الكافية على وقوعها .
مادة (19)
للنيابة العامة أو سلطة التحقيق المختصة ‎٠‏ بحسب الأحوال ؛ فى الجرائم المنتصوص
عليها بالمواد (؟١. ‎1١9 1١6‏ ؟١5)‏ من هذا القانون . أن تصدر أمراً مؤقمًا بغلق المقار .
والأماكن . والمساكن , ومحال الإيواء على أن يصدر القرار من رئيس نيابة على الأقل ,
وتعتبر الأمتعة والأثاث المضبوط فيها فى حكم الأشياء المحجوز عليها إداريًا بمجرد
ضبطها حتى يفصل فى الدعوى نهائيًا . وتسلم بعد جردها وإثباتها فى محضر إلى حارس
يكلف بحراسة الأختام الموضوعة على المقر أو المكان أو المحل أو المسكن المغلق . فإن لم
توجد مضبوطات كلف بالحراسة على الأختام وبالطريقة ذاتها . ويترتب على صدور الحكم
بالبراءة سقوط أمر الغلق .
وللنيابة العامة أو سلطة التحقيق المختصة وقف المواقع المنصوص عليها فى الفقرة
الأولى من المادة (89؟) من هذا القانون , أو حجبها . أو حجب ما يتضمنه أى وجه من
أوجه الاستخدام المنصوص عليها فى هذه المادة . والتتحفظ على الأجهزة والمعدات
المستخدمة فى الجريمة .
مسادة ‎)0١(‏
‏تخصص دائرة أو أكثر من دوائر محاكم الجنايات . يكون رئيس كل منها
بدرجة رئيس بمحاكم الاستئناف , لنظر الجنايات من الجرائم الإرهابية , والجرائم المرتبطة
بهذه الجنايات .


الجريدة الرسمية - العدد # (مكرر) فى ‎١0‏ أغسطس سنة ‎170١6‏ 0”
وتخصص دوائر فى المحاكم الابتدائية برئاسة رئيس بالمحكمة على الأقل لنظر الجنح
من الجرائم الإرهابية والجرائم المرتبطة بهذه الجنح .
كما تخصص دوائر فى المحاكم الابتدائية برئاسة رئيس بالمحكمة على الأقل وعضوين
أحدهما على الأقل بدرجة رئيس لنظر الطعون بالاستئناف فى الأحكام الصادرة فى هذه
الجرائم .
ويفصل فى القضايا المشار إليها فى هذه المادة على وجه السرعة . وطبقًا للإجراءات
المقررة فى هذا القانون وقانون الإجراءات الجنائية .
مسادة ‎)0١(‏
‏تختص النيابة العامة أو سلطة التحقيق المختصة . بحسب الأحوال ؛ أو المحكمة
التى تنظر أو تحال إليها أية جريمة إرهابية » بنظر الجرائم المرتبطة بها .
مادة (09)
لا تنتقضى الدعوى الجنائية فى الجرائم الإرهابية . ولا تسقط العقوبة المحكوم بها
فيها بمضى المدة .
مادة (07)
لرئيس الجمهورية . متى قام خطر من أخطار الجرائم الإرهابية أو ترتب عليها كوارث
بيئية » أن يصدر قراراً باتخاذ التدابير المناسبة للمحافظة على الأمن والنظام العام , بما فى
ذلك إخلاء بعض المناطق أو عزلها أو حظر التجول فيها . على أن يتضمن القرار تحديد
المنطقة المطبق عليها لمدة لا تجاوز ستة أشهر .
ويجب عرض هذا القرار على مجلس النواب خلال الآيام السبعة التالية ليقرر ما يراه
بشأنه . فإذا كان المجلس فى غير دور الانعقاد العادى وجبت دعوته للانعقاد فوراً ,
فإذا كان المجلس غير قائم وجب أخذ موافقة مجلس الوزراء » على أن يعرض على مجلس
النواب الجديد فى أول اجتماع له . ويصدر القرار بموافقة أغلبية عدد أعضاء المجلس ,
فإذا لم يعرض القرار فى الميعاد المشار إليه . أو عرض ولم يقره المجلس اعتبر القرار كأن
لم يكن ما لم ير المجلس خلاف ذلك .


5 الجريدة الرسمية - العدد *" (مكرر) فى ‎١0‏ أغسطس سنة ‎5١١0‏

ويجوز لرئيس الجمهورية مد مدة التدبير المشار إليها بالفقرة الأولى من هذه المادة بعد
موافقة أغلبية أعضاء مجلس النواب .

وفى الحالات العاجلة التى تتخذ فيها التدابير المشار إليها فى هذه المادة بمقتضى
أوامر شفوية أن تعزز كتابةً خلال ثمانية أيام .

مادة (01)

تلتزم الدولة بإبرام وثيقة تأمين إجبارى شامل مع شركات التأمين . لتغطية جميع
الأخطار الناجمة عن الجرائم الإرهابية التى تصيب أى فرد من أفراد القوات المسلحة أو
قوات الشرطة المكلفة بمكافحة الإرهاب , حال تصديها لتلك الجرائم , بما فى ذلك حالات
الوفاة أو العجز الكامل أو الجزئى . على أن تتضمن الوثيقة التزام الشركة بسداد
تعويضات مؤقتة للمضرورين فور وقوع الخطر خصمً من مبلغ التأمين .

وفى جميع الأحوال . تلتزم شركة التأمين بسداد مبلغ التأمين وفقًا للوثيقة . وذلك
دون الإخلال بحق المضرور أو ورثته أو شركة التأمين فى اللجوء للقضاء .

ويتم التأمين لدى شركة أو أكثر من شركات التأمين المسجلة لدى الهيئة العامة
للرقابة المالية . والمرخص لها بمزاولة تلك الأنشطة التأمينية طبقًا لأحكام قانون الإشراف
والرقابة على التأمين فى مصر .

ولرئيس مجلس الوزراء تخصيص جزء من الأموال أو المتحصلات المحكوم بمصادرتها
فى الجرائم الإرهابية لسداد التزامات الدولة فى وثيقة التأمين الإجبارى المنصوص عليها
فى الفقرة الأولى من هذه المادة .$b43$, '2015-08-15', 'active' FROM ins_art_UG49861UG49862_1;

