باسم الشكب
رئيس الجمهورية

قرر مجلس النواب القانون الآتى نصه . وقد أصدرناه :

( المادة الأولى )

فى تطبيق أحكام هذا القانون , يقصد بالألفاظ والعبارات التالية المعنى المبين قرين

الأحكام القضائية : الأحكام الصادرة من محاكم القضاء المدنى .

المحكمة المختصة : محكمة القاهرة للأمور المستعجلة .

اللجنة : لجنة إجراءات التحفظ والإدارة والتصرف فى أموال الجماعات الإرهابية والإرهابيين .

الأموال : جميع الأصول أو الممتلكات يا كان نوعها سواء أكانت مادية أو معنوية
ثابتة أو منقولة بما فى ذلك المستندات والعملات الوطنية أو الأجنبية أو الأوراق المالية
أو التجارية والصكوك والمحررات المبينة لكل ما تقدم , وأيا كان نوعها أو شكلها
بما فى ذلك الشكل الرقمى أو الإلكترونى وجميع الحقوق المتعلقة بكل منها .

الجهات والهيئات : جميع الجهات والهيئات الحكومية وغير الحكومية .

البيانات : جميع البيانات المتعلقة بشخص طبيعى أو معنوى يا كانت صورتها
اقتصادية , أو ثقافية , أو فكرية , أو اجتماعية .

البنوك : البنك المركزى وجميع البنوك الحكومية والمشتركة والخاصة والأجنبية
على أرض الدولة المصرية .

التحفظ : كافة الإجراءات القضائية والإدارية المؤدية إلى التحفظ على المال والحفاظ
عليه منذ تاريخ التحفظ عليه . وذلك على النحو المبين بهذا القانون .


الجريدة الرسمية - العدد ‎١5‏ (مكرر) فى ‎7١‏ أبريل سنة ‎7.١4‏ 0 الم

الإدارة : إدارة المال على النحو المبين بهذا القانون والقانون المدنى وقانون المرائعات
المدنية والتجارية .

التصرف : التصرف فى المال محل التحفظ على النحو المبين بهذا القانون والقانون
المدنى وقانون المرافعات المدنية والتجارية .

الجهات المساعدة : جميع الجهات الحكومية أيا كانت طبيعتها , والتى ترى اللجنة
الاستعانة بها فى سبيل تحقيق الغرض من قيامها .

الاستدلالات : جميع الأوراق التى تقدم للجنة من جهات الاختصاص و/المتعلقة
بالكشف عن الأموال والأشخاص محل تنفيذ الأحكام القضائية .

الضمانات : مجموعة الإجراءات التى تحافظ على حقوق الغير حسن النية .

(المادة الثانية )

تنشا لجنة مستقلة فى أدائها لعملها ذات تشكيل قضائى تختص دون غيرها باتخاذ
جميع الإجراءات المتعلقة بتنفيذ الأحكام القضائية الصادرة باعتبار جماعة أو شخص
ينتمى إلى جماعة أو جماعات إرهابية . وذلك استثناء من أحكام قانون المرافعات المدنية
والتجارية . فيما يتعلق بتنفيذ الأحكام القضائية وتحديد القائمين على التنفيذ الجبرى
للأحكام القضائية .

ويكون مقر اللجنة مدينة القاهرة . وتعقد اجتماعاتها فى مقر محكمة استئناف القاهرة ,
وذلك إلى حين تدبير مقر مستقل لها .

(المادة الثالثة )

تشكل اللجنة من سبعة أعضاء من بين قضاة محاكم الاستئناف . على أن يكون
كل منهم بدرجة رئيس استئناف يرشحهم وزير العدل . ويصدر بندبهم قرار من رئيس الجمهورية
بعد موافقة مجلس القضاء الأعلى لمدة سنة قابلة للتجديد . وتكون رئاستها لأقدم الأعضاء ,
ولهم جميع الحقوق المالية المقررة لأقرانهم وتصرف لهم من محكمة استئناف القاهرة شاملة
جميع الحوافز والبدلات .


الجريدة الرسمية - العدد ‎١١‏ (مكرر) فى ‎5١‏ أبريل سنة 7.14
(المادة الرايعة )
تتولى اللجنة تنفيذاً للأحكام القضائية المنصوص عليها فى هذا القانون إجراء أعمال
حصر الأموال الخاصة بجميع هذه الأحكام , أيَا كانت صورتها , ولها اتخاذ جميع الإجراءات
التى تكشف عنها والاستعانة بجميع الجهات التى ترى الاستعانة بها فى هذا الشأن .
( المادة الخامسة )
تتلقى اللجنة جميع المستندات والأوراق والبيانات الخاصة بتنفيذ الأحكام القضائية ,
وللجنة سماع من ترى لزوم سماعه بعد تحليفه اليمين القانونية وتعرض ما انتهت إليه
على قاضى الأمور الوقتية لإصدار أمر مسبب بالتحفظ , ويكون الأمر الصادر بالتحفظ نافذاً
فور صلوره .
وعلى اللجنة إعلان الأمر لذوى الشأن خلال ثلاثة أيام من تاريخ صدوره بالطرق
المقررة فى قانون المرافعات المدنية والتجارية . ولها فى سبيل ذلك الاستعانة برجال
السلطة العامة .
(المادة السسادسسية )
لكل ذى صفة أو مصلحة أن يتظلم من القرار الصادر من اللجنة خلال ثمانية أيام
من تاريخ إعلانه إعلانًا قانونيا على النحو المبين بالمادة الخامسة من هذا القانون أمام المحكمة
المختصة المنصوص عليها فى هذا القانون . وعلى المحكمة أن تفصل فى التظلم خلال
ثلاثين يومًا من تاريخ قيده أمامها بالإجراءات المعتادة . وللمحكمة أن تحكم بوقف تنفيذ
القرار أو تأييده أو إلغائه .
ولكل ذى صفة أو مصلحة استئناف الحكم خلال عشرة أيام من تاريخ علمه '
وعلى المحكمة المختصة المنصوص عليها فى هذا القانون أن تفصل فى الاستئناف خلال
ثلاثين يومًا من تاريخ قيد الاستئناف بجداولها , ويعد الحكم الصادر فى هذا الشأن نهائيًا ,
وغير قابل للطعن عليه .


الجريدة الرسمية - العدد ‎١١‏ (مكرر) فى ‎5١‏ أبريل سنة ‎50١4‏ 7 0
( المادة السابعة )
للجنة أن تطلب من المحكمة المختصة المنصوص عليها فى هذا القانون أن تصدر أمراً
بالتأشير على هامش التسجيلات الخاصة بالحقوق العينية الخاصة بالأموال المتحفظ عليها .
وفى جميع الأحوال . لا يحتج بأى حق عينى أو شخصى لصالح الغير بعد تاريخ الإخطار
الوارد بالمادة الرابعة أو التأشير الصادر بناءً على طلب اللجنة . ويجوز التظلم
فى هذا الأمر من كل ذى مصلحة أمام المحكمة المختصة وبالإجرا ءات المنصوص عليها فى قانون
المرافعات المدنية والتجارية وقانون الشهر العقارى والتوثيق وقانون السجل العينى .
ويقيد فى سجل خاص بقلم كتاب المحكمة مصدر الأمر بالتأشير تثثبت فيه القرارات
الصادرة فى هذا الشأن . ويترتب على انتهاء قرار التحفظ أو إلغائه زوال جميع الآثار
التى ترتبت على التأشير .
( المادة الثامنة )
على كل من يحوز عقاراً أو منقولا مملوكًا للمتحفظ على أمواله أو يكون مدينًا له
أن يخطر اللجنة بما فى ذمته . وذلك خلال ثلاثين يوما من تاريخ صدور الحكم .
وإذا قامت أدلة على وجود أموال للمتحفظ على أمواله لدى الغير . جاز للجنة
أن تطلب من قاضى الأمور الوقتية أن يصدر أمراً بتكليف الغير بعدم الوفاء له بما للمدين
لدى الغير سواء كانت تلك الأموال ثابتة أو منقولة أو دينًا أو أجرة أو قيمًا منقولة
أو أى حق آخر , ويكون لهذا الأمر كل ما يرتبه القانون من حجز ما للمدين لدى الغير من آثار .
(المادة التاسعة )
تعين اللجنة من تراه من الخبراء المتتخصصين لإدارة الأموال , وعلى من يتولى الإدارة
مباشرتها بعد استلامها وجردها بحضور ذوى الشأن ما لم تقم حالة ضرورة لدى القائمين
على الإدارة » وذلك كله طبقما للأحكام المقررة فى القانون المدنى فى شأن الإدارة
والوديعة والحراسة .


5 الجريدة الرسمية - العدد ‎١١‏ (مكرر) فى ‎5١‏ أبريل سنة 7.14

وللجنة أن تطلب من القائمين على إدارة المال قبل التحفظ الاستمرار فى الإدارة
إذا رأت اللجنة ضرورة لذلك .

وتضاف مصاريف الإدارة والقائمين عليها إلى جانب المال محل الإدارة » وتحدد حقوق
القائمين على الإدارة بموجب قرار من اللجنة .

وللجنة بناءً على طلب مؤيد بالمستندات تقرير مبلغ للمتحفظ على أمواله
لمواجهة احتياجاته .

(المادة العاشرة )

تلتزم الجهات والهيئات والبنوك بالتعاون مع اللجنة وقكين أعضائها أو ممثليهم
من الاطلاع على كل ما لديها من مستندات ومعلومات أو بيانات ذات الصلة باختصاصها
وتقديم جميع البيانات والمستندات والدفاتر المطلوبة فى المواعيد التى تحددها . وتنفيذ
القرارات الصادرة عنها كل فيما يخصه مع مراعاة أحكام القوانين ذات الصلة ,
وذلك دون الإخلال بمقتضيات الأمن القومى واعتبارات السرية للوثائق والبيانات والمعلومات
ذات الطبيعة الأمنية الخاصة .

(المادة الحادية عشرة )

مع مراعاة حقوق الغير حسن النية » يكون للجنة متى صار حكم التحفظ نهائيًا التصرف
فى الأموال محل التحفظ على النحو المبين فى القانون المدنى والمرافعات المدنية والتجارية
متى كان منطوق الحكم قد نص على التصرف فى المال , وذلك بنقل ملكيته إلى الخزانة
العامة بناء على طلب اللجنة من المحكمة المختصة التصرف فى المال .

(المادة الثانية عشرة )

تضع اللجنة لائحة عملها الداخلى وأمانتها الفنية والعاملين المنتتدبين إليها
من الجهات والهيئات القضائية ؛ على أن يتقاضى جميع المنتدبين حقوقهم المالية من جهات عملهم
الأصلية والمقررة لهم قبل ندبهم وما يستجد منها أثناء الندب .


الجريدة الرسمية - العدد ‎١١‏ (مكرر) فى ‎5١‏ أبريل سنة ‎1.١4‏ “ا
(المادة الثالثة عشرة )

تشكل اللجنة أمانتها الفنية برئاسة أمين عام يتم ندبه طول الوقت من بين قضاة
محاكم الاستئناف , وعدد كاف من القضاة بالمحاكم الابتدائية بدرجة رئيس محكمة (أ)
طول الوقت يتقاضى كل منهم جميع الحقوق المالية من محكمة القاهرة الابتدائية , بما فيها
كافةالحوافز والبدلات . وبمكثل عن وزارة المالية . وثمكل عن وزارة الداخلية
تتحمل جهة عملهما حقوقهما المالية .

وللجنة الاستعانة بالقائمين على تنفيذ الأحكام بقلم محضرى محكمة جنوب
القاهرة الابتدائية .

(المادة الرايعة عشرة )

للجنة فى سبيل أداء عملها أن تستعين بمن ترى لزوم الاستعانة بهم من أى جهة
حكومية أو غير حكومية أو رقابية , ولها فى سبيل ذلك سماع أقوالهم وتكليف أى منهم
بتقديم ما لديه من مستندات أو بيانات أو معلومات متى رأت سببًا موجبًا لذلك ,
وذلك دون الإخلال بمقتضيات الأمن القومى واعتبارات سرية المعلومات والبيانات .

( المادة الخامسة عشرة )

مع عدم الإخلال بأى عقوبة نص عليها قانون آخر . يعاقب بالحبس مدة لا تزيد على
سنة وبغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه , أو بإحدى هاتين
العقوبتين . كل من امتنع عن إمداد اللجنة بالمعلومات أو البيانات أو المستندات اللازمة
لأداء أعمالها مع عزله من وظيفته مدة مماثلة لمدة الحبس المقضى بها .

ويعاقب بذات العقوبة كل من اتصل عمله باللجنة أو أمانتها الفنية فأفشى ما حصلت
عليه اللجنة من بيانات أو معلومات على النحو المبين فى هذا القانون .


6 الجريدةالرسمية - العدد ‎١١5‏ (مكرر) فى ‎7١‏ أبريل سنة ‎7.١14‏
‏(المادة السادسة عشرة )
تعرض جميع القرارات السابقة على العمل بهذا القانون على اللجنة , ولها إعادة
النظر فيها طبقًا للإجراءات والأوضاع المنصوص عليها فى هذا القانون .
(المادة السابعة عشرة )
بنشر هذا القانون فى الجريدة الرسمية , ويعمل به اعتبارا من اليوم التالى لتاريخ نشره ,
ويلغى كل ما يخالف أحكامه .
يبصم هذا القانون بخاتم الدولة » وينفذ كقانون من قوانينها .
