-- ===== وثائق مُستبعَدة عمداً من هذه الدفعة (راجع التقرير المرفق) =====
-- تعميم-3-2026: استُبعد عمداً: (1) رقمه (3) لعام 2026 يتعارض فعلياً مع قرار مجلس إدارة آخر مُدخَل سلفاً بنفس الرقم والسنة (قرار رقم 3 لسنة 2026 بتعديل قرار رقم 2 لسنة 2025 بشأن استثمار أموال شركات التأمين) — قيد UNIQUE(law_no, law_year) يمنع إدراج الاثنين معاً بنفس الرقم، وإدراج أحدهما بديلاً عن الآخر يُفقِد بيانات حقيقية. (2) الملف صورة ضوئية بجودة رديئة تمنع حتى قراءة رقم التعميم بثقة (استُخرج آلياً كـ«رقم 1» خطأً). (3) نطاقه إدارى محدود (موافاة الجهاز المركزى للتعبئة العامة والإحصاء ببيانات مالية) وليس ضابطاً تنظيمياً جوهرياً لمكافحة غسل الأموال. يحتاج قراراً تصنيفياً منفصلاً منك إن أردت إدراجه رغم ذلك (مثلاً بإضافة حقل يُميّز نوع الوثيقة فى قاعدة البيانات).
-- إجراءات-العناية-الواجبة: استُبعدت عمداً: دليل إجرائى (إصدار فبراير 2020) صادر عن وحدة مكافحة غسل الأموال، لا يحمل أى رقم قرار أو تشريع رسمى إطلاقاً (لا فى عنوانه ولا فى متنه) — بنية جدول laws تشترط law_no فريداً (NOT NULL)، واختراع رقم له يُمثِّل تلفيقاً لاستشهاد قانونى غير موجود فعلياً. يحتاج قراراً تصميمياً منك: إما إضافة نوع محتوى منفصل للأدلة الإرشادية غير المرقّمة بالمنصة مستقبلاً، أو ربطه يدوياً كملحق لقرار 161/2024 أو للقانون 80/2002.

COMMIT;